// C++ reference for Crucible's editor (hover / completion / signature help).
// Target: clang++ -std=c++20 with libc++. The harness already includes <bits/stdc++.h>
// and `using namespace std;`, so headers below are informational.
export default [
  // ───────────── keywords & language ─────────────
  { name: 'auto', kind: 'keyword', sig: 'auto x = expr;', doc: 'Deduce the type from the initializer. `auto` copies; use `auto&` to modify in place and `const auto&` to avoid copies of big elements. Gotcha: `auto x = 0;` is `int` — write `0LL` for long long.', example: 'for (auto& row : grid) for (auto& c : row) c = 0;\nauto [lo, hi] = minmax(a, b);' },
  { name: 'for', kind: 'keyword', sig: 'for (init; cond; step) { ... }  |  for (decl : range) { ... }', doc: 'Classic counted loop, or **range-for** over any container. Range-for by value copies each element — use `auto&`/`const auto&`. Don\'t insert/erase in the container while range-iterating.', example: 'for (int i = 0; i < n; i++) { }\nfor (const auto& [k, v] : mp) { }', insert: 'for (${1:auto}& ${2:x} : ${3:v}) {\n	$0\n}' },
  { name: 'fori', kind: 'snippet', sig: 'for (int i = 0; i < n; i++)', doc: 'Indexed loop snippet. Comparing `int i < v.size()` mixes signed/unsigned; `(int)v.size()` silences it and avoids `v.size() - 1` underflow on empty vectors.', example: 'for (int i = 0; i < n; i++) sum += a[i];', insert: 'for (int ${1:i} = 0; ${1:i} < ${2:n}; ${1:i}++) {\n	$0\n}' },
  { name: 'while', kind: 'keyword', sig: 'while (cond) { ... }', doc: 'Loop while *cond* is true; checked before each iteration.', example: 'while (!q.empty()) {\n  int u = q.front(); q.pop();\n}', insert: 'while (${1:cond}) {\n	$0\n}' },
  { name: 'do', kind: 'keyword', sig: 'do { ... } while (cond);', doc: 'Loop that runs at least once. Note the trailing semicolon.', example: 'sort(s.begin(), s.end());\ndo { cout << s << "\\n"; } while (next_permutation(s.begin(), s.end()));', insert: 'do {\n	$0\n} while (${1:cond});' },
  { name: 'if', kind: 'keyword', sig: 'if (init; cond) { ... }', doc: 'Conditional; C++17 allows an init-statement: `if (auto it = m.find(k); it != m.end())`.', example: 'if (auto it = m.find(k); it != m.end()) cout << it->second;\nif (x > 0) pos++;', insert: 'if (${1:cond}) {\n	$0\n}' },
  { name: 'else', kind: 'keyword', sig: 'else { ... }', doc: 'Alternative branch of an `if`.', example: 'if (x % 2 == 0) even++;\nelse odd++;', insert: 'else {\n	$0\n}' },
  { name: 'switch', kind: 'keyword', sig: 'switch (expr) { case K: ... break; default: ... }', doc: 'Branch on an integral/enum value. Cases fall through without `break`; declaring variables in a case needs braces.', example: 'switch (op) {\ncase \'+\': r = a + b; break;\ncase \'-\': r = a - b; break;\ndefault: r = 0;\n}', insert: 'switch (${1:expr}) {\ncase ${2:0}:\n	$0\n	break;\ndefault:\n	break;\n}' },
  { name: 'return', kind: 'keyword', sig: 'return expr;', doc: 'Exit the function with a value. Brace-init works: `return {i, j};` for `vector<int>` or `pair`. Never return a reference to a local.', example: 'if (n <= 1) return n;\nreturn {i, j};  // vector<int> / pair' },
  { name: 'break', kind: 'keyword', sig: 'break;', doc: 'Exit the innermost loop or switch.', example: 'for (int x : v) {\n  if (x < 0) break;\n  sum += x;\n}' },
  { name: 'continue', kind: 'keyword', sig: 'continue;', doc: 'Skip to the next loop iteration.', example: 'for (int x : v) {\n  if (x % 2) continue;\n  sum += x;\n}' },
  { name: 'const', kind: 'keyword', sig: 'const T name', doc: 'Read-only. Pass large inputs as `const vector<int>&` to avoid an **O(n)** copy per call. `const` member functions promise not to mutate `*this`.', example: 'int total(const vector<int>& v) { return accumulate(v.begin(), v.end(), 0); }' },
  { name: 'constexpr', kind: 'keyword', sig: 'constexpr T name = value;', doc: 'Compile-time constant / function evaluable at compile time. `constexpr int MOD = 1e9 + 7;`', example: 'constexpr int MOD = 1\'000\'000\'007;\nconstexpr int dx[] = {0, 1, 0, -1};' },
  { name: '&', kind: 'keyword', sig: 'T& ref = obj;', doc: 'Reference: an alias, not a copy. Use `T&` parameters to modify the caller\'s object (e.g. DFS visited arrays) and `const T&` to read without copying. In a lambda capture, `[&]` captures everything by reference.', example: 'void dfs(int u, vector<vector<int>>& g, vector<bool>& seen);' },
  { name: 'struct', kind: 'keyword', sig: 'struct Name { members; };', doc: 'Class with public members by default. Supports constructors, methods and `operator<` for use in `set`/`map`/`sort`.', example: 'struct Edge { int u, v, w; };\nsort(es.begin(), es.end(), [](auto& a, auto& b){ return a.w < b.w; });', insert: 'struct ${1:Name} {\n	$0\n};' },
  { name: 'class', kind: 'keyword', sig: 'class Name { public: ... };', doc: 'User type with private members by default. LeetCode wraps solutions in `class Solution { public: ... };` and design problems in a class whose methods you implement.', example: 'class Solution {\npublic:\n  int solve(vector<int>& nums) { return (int)nums.size(); }\n};', insert: 'class ${1:Name} {\npublic:\n	$0\n};' },
  { name: 'public', kind: 'keyword', sig: 'public:', doc: 'Access specifier: following members are accessible from outside the class.', example: 'class Counter {\npublic:\n  int n = 0;\n};' },
  { name: 'private', kind: 'keyword', sig: 'private:', doc: 'Access specifier: following members are only accessible inside the class.', example: 'class Stack {\nprivate:\n  vector<int> data;\n};' },
  { name: 'this', kind: 'keyword', sig: 'this', doc: 'Pointer to the current object inside a member function: `this->x`.', example: 'struct P { int x; void set(int x) { this->x = x; } };' },
  { name: 'template', kind: 'keyword', sig: 'template <typename T> ...', doc: 'Generic function/class parameterised by types or constants.', example: 'template <typename T>\nT sq(T x) { return x * x; }', insert: 'template <typename ${1:T}>' },
  { name: 'typename', kind: 'keyword', sig: 'template <typename T>', doc: 'Introduces a type parameter in a template (same as `class` there).', example: 'template <typename T>\nvoid print(const vector<T>& v) { for (const T& x : v) cout << x << " "; }' },
  { name: 'lambda', kind: 'snippet', sig: '[captures](params) -> ret { body }', doc: 'Anonymous function. Captures: `[]` none, `[&]` all by reference, `[=]` all by copy, `[&x, y]` mixed, `[this]` members. Recursive lambdas: C++23 `this auto&` or use `function<int(int)>`.', example: 'auto cmp = [](const auto& a, const auto& b) { return a[1] < b[1]; };\nfunction<void(int)> dfs = [&](int u) { for (int v : g[u]) dfs(v); };', insert: '[${1:&}](${2:auto x}) {\n	$0\n}' },
  { name: 'nullptr', kind: 'keyword', sig: 'nullptr', doc: 'Typed null pointer literal (`std::nullptr_t`). Prefer over `NULL`/`0`: `if (root == nullptr)` or simply `if (!root)`.', example: 'ListNode* prev = nullptr;\nif (root == nullptr) return 0;' },
  { name: 'using', kind: 'keyword', sig: 'using Alias = Type;  |  using namespace ns;', doc: 'Type alias (`using ll = long long;`) or import a namespace. The harness already does `using namespace std;`.', example: 'using ll = long long;\nusing pii = pair<int, int>;' },
  { name: 'namespace', kind: 'keyword', sig: 'namespace name { ... }', doc: 'Groups names to avoid collisions. Standard library lives in `std`.', example: 'namespace util { int sq(int x) { return x * x; } }\nint y = util::sq(3);  // 9' },
  { name: 'typedef', kind: 'keyword', sig: 'typedef Type Alias;', doc: 'C-style type alias; `using Alias = Type;` is the modern equivalent.', example: 'typedef long long ll;\nll big = 1LL << 40;' },
  { name: 'enum', kind: 'keyword', sig: 'enum class Name { A, B };', doc: '`enum class` gives scoped, strongly typed enumerators (`Name::A`); plain `enum` leaks names and converts to int.', example: 'enum class Dir { Up, Down };\nDir d = Dir::Up;' },
  { name: 'static', kind: 'keyword', sig: 'static T name;', doc: 'Static locals/members persist across calls and **across test cases** — reset them. Comparator functions inside a class must be `static` to pass to `sort`.', example: 'int nextId() { static int id = 0; return ++id; }  // 1, 2, 3, ...' },
  { name: 'static_cast', kind: 'keyword', sig: 'static_cast<T>(expr)', params: [{ label: 'expr', doc: 'value to convert' }], doc: 'Explicit, checked-at-compile-time conversion, e.g. `static_cast<long long>(a) * b` to avoid int overflow, or `(int)v.size()`.', example: 'long long area = static_cast<long long>(w) * h;' },
  { name: 'sizeof', kind: 'keyword', sig: 'sizeof(type_or_expr)', params: [{ label: 'type_or_expr', doc: 'a type (parenthesised) or an expression; not evaluated' }], doc: 'Size in bytes. For containers use `.size()` — `sizeof(v)` is the vector object, not its contents.', example: 'int a[10];\nsize_t n = sizeof(a) / sizeof(a[0]);  // 10' },
  { name: 'new', kind: 'keyword', sig: 'new T(args)', params: [{ label: 'args', doc: 'constructor arguments' }], doc: 'Heap-allocate an object, returning a pointer (e.g. `new TreeNode(5)`, `new ListNode(0)`). Prefer containers/`make_unique` in your own code.', example: 'TreeNode* root = new TreeNode(5);\nroot->left = new TreeNode(3);' },
  { name: 'delete', kind: 'keyword', sig: 'delete ptr;  |  delete[] arr;', doc: 'Free memory from `new` (`delete[]` for `new T[n]`). Judges rarely require it.', example: 'int* buf = new int[n];\ndelete[] buf;' },
  { name: 'operator', kind: 'keyword', sig: 'bool operator<(const T& o) const', params: [{ label: 'o', doc: 'the other operand (right-hand side)' }], doc: 'Overload an operator. Defining `operator<` lets a struct be sorted and used in `set`/`map`/`priority_queue`. C++20: `auto operator<=>(const T&) const = default;`.', example: 'struct P { int x, y;\n  bool operator<(const P& o) const { return tie(x, y) < tie(o.x, o.y); } };' },
  { name: 'bool', kind: 'type', sig: 'bool', doc: 'Boolean `true`/`false`. `vector<bool>` is bit-packed (no `bool&` references); use `vector<char>` if that bites.', example: 'bool found = false;\nvector<bool> seen(n, false);' },
  { name: 'true', kind: 'constant', sig: 'true', doc: 'Boolean true.', example: 'bool ok = true;\nwhile (true) { if (++i == n) break; }' },
  { name: 'false', kind: 'constant', sig: 'false', doc: 'Boolean false.', example: 'vector<bool> vis(n, false);' },
  { name: 'int', kind: 'type', sig: 'int', doc: '32-bit signed integer (±2.1e9). Overflow is UB — use `long long` for big sums/products.', example: 'int n; cin >> n;\nint mid = lo + (hi - lo) / 2;  // avoids lo + hi overflow' },
  { name: 'long long', kind: 'type', sig: 'long long', doc: '64-bit signed integer (±9.2e18). Cast **before** multiplying: `1LL * a * b`. LeetCode often returns `long long`.', example: 'long long sum = accumulate(v.begin(), v.end(), 0LL);' },
  { name: 'size_t', kind: 'type', sig: 'size_t', doc: 'Unsigned type of `.size()`. `v.size() - 1` underflows to a huge number when empty; cast to int first.', example: 'for (size_t i = 0; i < v.size(); i++) cout << v[i];' },
  { name: 'char', kind: 'type', sig: 'char', doc: 'Single character; `c - \'a\'` maps letters to 0..25, `c - \'0\'` gives digit value.', example: 'char c = s[i];\nint idx = c - \'a\';  // 0..25' },
  { name: 'double', kind: 'type', sig: 'double', doc: '64-bit float. Print with `fixed << setprecision(k)`; compare with an epsilon.', example: 'double avg = (double)sum / n;\ncout << fixed << setprecision(2) << avg;' },
  { name: 'structured binding', kind: 'snippet', sig: 'auto [a, b] = expr;', doc: 'C++17: unpack pairs, tuples, arrays and structs. Combine with range-for over maps.', example: 'for (auto& [key, val] : mp) { }\nauto [x, y] = q.front();', insert: 'auto [${1:a}, ${2:b}] = ${3:p};' },
  { name: '#include', kind: 'directive', sig: '#include <header>', doc: 'Include a header. `<bits/stdc++.h>` pulls in everything (the Crucible harness provides it).', example: '#include <bits/stdc++.h>\nusing namespace std;', insert: '#include <${1:vector}>' },

  // ───────────── iostream ─────────────
  { name: 'cout', owner: 'std', kind: 'constant', sig: 'std::ostream cout', doc: 'Standard output stream: `cout << x << " " << y << "\\n";`. Prefer `"\\n"` over `endl` in loops (endl flushes).', example: 'cout << ans << "\\n";\ncout << a << " " << b << "\\n";', header: '#include <iostream>', learn: {
    summary: "the standard output stream",
    what: "std::cout (\"character output\") is an object that stands for your program's output: the text the judge reads. You send values to it with the << operator, read as \"goes into\": std::cout << x puts x into the output. You can chain several << in one statement, and numbers are converted to text automatically. Nothing adds a line break for you; send \"\\n\" (or std::endl) when you want one.",
    example: "int n = 3;                                   // something to show\nstd::cout << \"n = \" << n << \"\\n\";            // n = 3, then a line break\nstd::cout << n * 2 << ' ' << n + 1 << \"\\n\";  // 6 4",
    watch: [
      "Needs #include <iostream>; write std::cout, or add using namespace std; to write cout.",
      "Values are not separated automatically: cout << 1 << 2 prints 12. Add \" \" yourself.",
      "std::endl also flushes the output, which is slow inside big loops; prefer \"\\n\"."
    ]
  }  },
  { name: 'cin', owner: 'std', kind: 'constant', sig: 'std::istream cin', doc: 'Standard input stream; `cin >> n` skips whitespace. `while (cin >> x)` reads until EOF. After `cin >>`, a following `getline` reads the leftover newline — call `cin.ignore()` first.', example: 'int n; cin >> n;\nvector<int> a(n);\nfor (auto& x : a) cin >> x;', header: '#include <iostream>', learn: {
    summary: "the standard input stream",
    what: "std::cin (\"character input\") is an object that stands for your program's input: the keyboard, or the test data the judge feeds in. Think of it as a stream, a queue of characters consumed from the front. The >> operator (read as \"comes out of cin into\") takes the next value and stores it in a variable, converting to that variable's type: std::cin >> n reads a number into an int, std::cin >> word reads one whitespace-separated word into a string. Spaces and newlines between values are skipped automatically.",
    example: "int age; std::string name;  // places to store the input\nstd::cin >> name >> age;    // input \"Ada 36\": name = \"Ada\", age = 36\nif (!std::cin) return 1;    // false if a read failed or input ran out",
    watch: [
      "std::cin >> s reads only one word; use std::getline(std::cin, s) for a whole line with spaces.",
      "If the input doesn't match the type (letters into an int), cin enters a failed state and every later read does nothing.",
      ">> leaves the newline behind, which trips up a following getline."
    ]
  }  },
  { name: 'cerr', owner: 'std', kind: 'constant', sig: 'std::ostream cerr', doc: 'Unbuffered error stream — debug prints that don\'t affect stdout.', example: 'cerr << "dbg i=" << i << " x=" << x << "\\n";', header: '#include <iostream>' },
  { name: 'endl', owner: 'std', kind: 'function', sig: 'std::ostream& endl(std::ostream& os)', params: [{ label: 'os', doc: 'stream' }], returns: 'std::ostream& — the same stream, after flushing', doc: 'Writes `\\n` **and flushes** — slow in big loops; use `"\\n"`.', example: 'cout << "done" << endl;  // newline + flush', header: '#include <iostream>' },
  { name: 'getline', owner: 'std', kind: 'function', sig: 'std::istream& getline(std::istream& is, std::string& str, char delim = \'\\n\')', params: [{ label: 'is', doc: 'input stream (cin or a stringstream)' }, { label: 'str', doc: 'receives the line, without the delimiter' }, { label: 'delim', doc: 'stop character' }], returns: 'std::istream& — the stream; converts to false at EOF/failure', doc: 'Read a whole line (or up to *delim*). Split CSV-like strings with a stringstream and `getline(ss, tok, \',\')`.', example: 'string line;\nwhile (getline(cin, line)) { }', header: '#include <string>', learn: {
    summary: "read a whole line into a string",
    what: "std::getline reads characters from an input stream (usually std::cin) into a std::string until it reaches the end of the line. Unlike std::cin >> s, which stops at the first space, getline keeps spaces, so you get the full line. The newline itself is consumed and thrown away; it is not stored in the string. Whatever the string held before is replaced.",
    params: {
      is: "the stream to read from: pass std::cin for the program's input",
      str: "a std::string variable that receives the line, e.g. line",
      delim: "optional stop character, default '\\n' (end of line). getline(std::cin, s, ',') reads up to a comma"
    },
    returns: "The stream itself. Used as a condition it is true if the read worked and false at end of input, so while (std::getline(std::cin, line)) { ... } processes every line.",
    example: "std::string line;                      // will hold the text\nif (std::getline(std::cin, line))      // read one full line, spaces included\n    std::cout << line.size() << \"\\n\";  // e.g. 11 for \"hello world\"",
    watch: [
      "After std::cin >> n, the newline is still waiting, so the next getline returns an empty string. Call std::cin.ignore() in between.",
      "Input with Windows line endings can leave a '\\r' at the end of the string."
    ]
  }  },
  { name: 'ios::sync_with_stdio', owner: 'std', kind: 'function', sig: 'ios::sync_with_stdio(bool sync)', params: [{ label: 'sync', doc: 'false to decouple from C stdio' }], returns: 'bool — the previous synchronization setting', doc: 'Fast I/O idiom: `ios::sync_with_stdio(false); cin.tie(nullptr);`. Afterwards don\'t mix `printf`/`scanf` with `cout`/`cin`.', example: 'ios::sync_with_stdio(false);\ncin.tie(nullptr);', header: '#include <iostream>' },
  { name: 'stringstream', owner: 'std', kind: 'type', sig: 'std::stringstream ss(str)', params: [{ label: 'str', doc: 'initial contents' }], doc: 'String-backed stream. `istringstream` to split words with `>>`, `ostringstream` to build strings (`ss.str()`).', example: 'istringstream ss(s); string w;\nwhile (ss >> w) words.push_back(w);', header: '#include <sstream>' },
  { name: 'setprecision', owner: 'std', kind: 'function', sig: 'setprecision(int n)', params: [{ label: 'n', doc: 'digits' }], returns: 'unspecified manipulator — use with << on a stream', doc: 'With `fixed`, prints *n* digits after the decimal point: `cout << fixed << setprecision(5) << x;`.', example: 'cout << fixed << setprecision(6) << x << "\\n";', header: '#include <iomanip>' },
  { name: 'cin.tie', owner: 'std', kind: 'function', sig: 'std::ostream* cin.tie(std::ostream* os)', params: [{ label: 'os', doc: 'stream to flush before each read; nullptr to untie' }], returns: 'std::ostream* — the previously tied stream (&cout by default)', doc: 'By default `cin` flushes `cout` before every read. `cin.tie(nullptr)` removes that flush — half of the fast-I/O idiom. Interactive problems may then need explicit flushes.', example: 'ios::sync_with_stdio(false);\ncin.tie(nullptr);', header: '#include <iostream>' },

  // ───────────── container types ─────────────
  { name: 'vector', owner: 'std', kind: 'type', sig: 'std::vector<T> v(n, value)', params: [{ label: 'n', doc: 'initial size' }, { label: 'value', doc: 'fill value (default T{})' }], doc: 'Dynamic array: **O(1)** index and amortised push_back; insert/erase in the middle is **O(n)**. 2-D: `vector<vector<int>> g(n, vector<int>(m, 0))`.', example: 'vector<int> v(n, 0);\nvector<vector<int>> dp(n + 1, vector<int>(m + 1));', header: '#include <vector>' },
  { name: 'string', owner: 'std', kind: 'type', sig: 'std::string s(n, ch)', params: [{ label: 'n', doc: 'length' }, { label: 'ch', doc: 'fill character' }], doc: 'Mutable byte string. `+=` a char is amortised **O(1)**; `s = s + t` copies (O(n)) — avoid in loops. Compare with `==`/`<`.', example: 'string s(3, \'a\'); // "aaa"\ns += \'b\';', header: '#include <string>' },
  { name: 'unordered_map', owner: 'std', kind: 'type', sig: 'std::unordered_map<K, V>', doc: 'Hash map: average **O(1)** lookup/insert, no order. Keys need `std::hash` — `pair` keys need a custom hash (or encode as `long long`). `m[k]` inserts a default if missing.', example: 'unordered_map<int, int> cnt;\nfor (int x : nums) cnt[x]++;', header: '#include <unordered_map>' },
  { name: 'map', owner: 'std', kind: 'type', sig: 'std::map<K, V, Compare = less<K>>', doc: 'Ordered map (red-black tree): **O(log n)** ops, iterates in key order, supports `lower_bound`. `begin()` is the smallest key, `prev(end())`/`rbegin()` the largest.', example: 'map<int, int> m;\nauto it = m.lower_bound(x);', header: '#include <map>' },
  { name: 'unordered_set', owner: 'std', kind: 'type', sig: 'std::unordered_set<T>', doc: 'Hash set: average **O(1)** insert/lookup, no order. Build from a range: `unordered_set<int> s(v.begin(), v.end());`.', example: 'unordered_set<int> seen;\nif (!seen.insert(x).second) dup = true;', header: '#include <unordered_set>' },
  { name: 'set', owner: 'std', kind: 'type', sig: 'std::set<T, Compare = less<T>>', doc: 'Ordered set of unique keys (tree): **O(log n)** insert/erase/find/lower_bound. `*s.begin()` min, `*s.rbegin()` max. Elements are const — erase and reinsert to change.', example: 'set<int> s = {3, 1, 2};\nint smallest = *s.begin();  // 1', header: '#include <set>' },
  { name: 'multiset', owner: 'std', kind: 'type', sig: 'std::multiset<T, Compare = less<T>>', doc: 'Ordered set allowing duplicates. Gotcha: `ms.erase(x)` removes **all** copies — use `ms.erase(ms.find(x))` to remove one. Useful as a sliding-window min/max structure.', example: 'multiset<int> ms = {1, 1, 2};\nms.erase(ms.find(1));  // removes one copy', header: '#include <set>' },
  { name: 'multimap', owner: 'std', kind: 'type', sig: 'std::multimap<K, V>', doc: 'Ordered map allowing duplicate keys; no `operator[]`. Use `equal_range(k)` to iterate a key\'s values.', example: 'multimap<int, string> mm;\nmm.insert({1, "a"});\nmm.insert({1, "b"});  // both kept', header: '#include <map>' },
  { name: 'queue', owner: 'std', kind: 'type', sig: 'std::queue<T>', doc: 'FIFO adapter (over deque). `push` back, `front` + `pop` front — `pop()` returns void. BFS staple.', example: 'queue<int> q; q.push(src);\nwhile (!q.empty()) { int u = q.front(); q.pop(); }', header: '#include <queue>' },
  { name: 'priority_queue', owner: 'std', kind: 'type', sig: 'std::priority_queue<T, Container = vector<T>, Compare = less<T>>', doc: 'Binary heap — **max-heap by default**. Min-heap: `priority_queue<int, vector<int>, greater<int>>` (or `greater<>`). push/pop **O(log n)**, top **O(1)**. Custom comparator returns true when *a* has **lower** priority than *b*.', example: 'priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq; // Dijkstra\npq.push({0, src});', header: '#include <queue>' },
  { name: 'stack', owner: 'std', kind: 'type', sig: 'std::stack<T>', doc: 'LIFO adapter. `push`, `top`, `pop` (returns void). A plain `vector` with push_back/back/pop_back works equally well.', example: 'stack<int> st;\nst.push(1);\nint t = st.top(); st.pop();', header: '#include <stack>' },
  { name: 'deque', owner: 'std', kind: 'type', sig: 'std::deque<T>', doc: 'Double-ended queue: **O(1)** push/pop at both ends plus random access. Monotonic-queue / 0-1 BFS workhorse.', example: 'deque<int> dq;\ndq.push_front(1);\ndq.push_back(2);', header: '#include <deque>' },
  { name: 'list', owner: 'std', kind: 'type', sig: 'std::list<T>', doc: 'Doubly linked list: **O(1)** insert/erase anywhere given an iterator, and other iterators stay valid. No random access (`l[i]` does not exist). Classic use: LRU cache as `list` + `unordered_map<K, list<...>::iterator>`.', example: 'list<int> l = {1, 2, 3};\nl.push_front(0);', header: '#include <list>' },
  { name: 'pair', owner: 'std', kind: 'type', sig: 'std::pair<T1, T2>', doc: 'Two values `.first`, `.second`. Compares lexicographically, so `sort` on `vector<pair<..>>` sorts by first then second. Build with `{a, b}` or `make_pair`.', example: 'pair<int, int> p = {1, 2};\nauto [a, b] = p;', header: '#include <utility>' },
  { name: 'tuple', owner: 'std', kind: 'type', sig: 'std::tuple<Ts...>', doc: 'Fixed-size heterogeneous group; access with `get<i>(t)` or structured bindings `auto [a, b, c] = t;`. Lexicographic comparison.', example: 'tuple<int, int, int> t = {d, r, c};\nauto [dist, row, col] = t;', header: '#include <tuple>' },
  { name: 'array', owner: 'std', kind: 'type', sig: 'std::array<T, N>', doc: 'Fixed-size array with value semantics and `.size()`; usable as map key and in sets (`array<int, 26>` letter counts).', example: 'array<int, 26> cnt{};\nfor (char c : s) cnt[c - \'a\']++;', header: '#include <array>' },
  { name: 'bitset', owner: 'std', kind: 'type', sig: 'std::bitset<N>', doc: 'Fixed-size bit array (N compile-time). Fast bitwise ops, `count()`, `to_string()`. Subset-sum DP: `bs |= bs << x`.', example: 'bitset<64> b(5);\ncout << b.count();  // 2', header: '#include <bitset>' },
  { name: 'function', owner: 'std', kind: 'type', sig: 'std::function<R(Args...)>', doc: 'Type-erased callable; lets a lambda call itself recursively. Slightly slower than a plain lambda.', example: 'function<int(int)> fib = [&](int n) { return n < 2 ? n : fib(n-1) + fib(n-2); };', header: '#include <functional>' },
  { name: 'greater', owner: 'std', kind: 'type', sig: 'std::greater<T>', doc: 'Comparator `a > b`. `sort(v.begin(), v.end(), greater<int>())` sorts descending; `greater<>` in priority_queue makes a min-heap.', example: 'priority_queue<int, vector<int>, greater<int>> minHeap;\nsort(v.begin(), v.end(), greater<int>());', header: '#include <functional>' },
  { name: 'less', owner: 'std', kind: 'type', sig: 'std::less<T>', doc: 'Default comparator `a < b` used by sort, set, map and priority_queue.', example: 'set<int, less<int>> s;  // same as set<int>', header: '#include <functional>' },
  { name: 'numeric_limits', owner: 'std', kind: 'type', sig: 'std::numeric_limits<T>::max()', doc: 'Type limits: `numeric_limits<int>::max()`, `::min()` (smallest *positive* for floating types — use `lowest()`), `numeric_limits<double>::infinity()`.', example: 'int best = numeric_limits<int>::max();\ndouble inf = numeric_limits<double>::infinity();', header: '#include <limits>' },
  { name: 'string_view', owner: 'std', kind: 'type', sig: 'std::string_view sv(str)', params: [{ label: 'str', doc: 'string or literal to view (not copied)' }], doc: 'Non-owning, read-only view of characters; `substr` is **O(1)** (no copy). Gotcha: it must not outlive the string it views — never bind it to a temporary `string`.', example: 'string_view sv = s;\nstring_view head = sv.substr(0, 3);  // no allocation', header: '#include <string_view>' },
  { name: 'optional', owner: 'std', kind: 'type', sig: 'std::optional<T>', doc: 'Holds either a `T` or nothing (`nullopt`). Test with `if (opt)` or `has_value()`; read with `*opt` or `value_or(def)`. `*opt` on an empty optional is UB.', example: 'optional<int> idx;\nfor (int i = 0; i < n; i++) if (a[i] == x) { idx = i; break; }\nif (idx) cout << *idx;', header: '#include <optional>' },
  { name: 'nullopt', owner: 'std', kind: 'constant', sig: 'inline constexpr nullopt_t nullopt', doc: 'The "no value" marker for `optional`: `return nullopt;` or `opt = nullopt;` to reset.', example: 'optional<int> best = nullopt;\nif (!best) cout << "none";', header: '#include <optional>' },
  { name: 'has_value', owner: 'optional', kind: 'method', sig: 'bool optional<T>::has_value()', returns: 'bool — true if a value is held (same as `if (opt)`)', doc: 'Check whether the optional is engaged before dereferencing.', example: 'if (res.has_value()) cout << *res;' },
  { name: 'value', owner: 'optional', kind: 'method', sig: 'T& optional<T>::value()', returns: 'T& — the held value; throws std::bad_optional_access if empty', doc: 'Checked access. `*opt` is the unchecked (faster, UB-if-empty) alternative.', example: 'int x = res.value();' },
  { name: 'value_or', owner: 'optional', kind: 'method', sig: 'T optional<T>::value_or(U&& default_value)', params: [{ label: 'default_value', doc: 'returned when empty' }], returns: 'T — copy of the held value, or default_value if empty', doc: 'Safe read with a fallback; returns by value (a copy).', example: 'int ans = res.value_or(-1);' },

  // ───────────── vector ─────────────
  { name: 'push_back', owner: 'vector', kind: 'method', sig: 'void vector<T>::push_back(const T& value)', params: [{ label: 'value', doc: 'element to append' }], returns: 'void', doc: 'Append to the end, amortised **O(1)**. Invalidates iterators/references if it reallocates.', example: 'v.push_back(x);' },
  { name: 'emplace_back', owner: 'vector', kind: 'method', sig: 'T& vector<T>::emplace_back(Args&&... args)', params: [{ label: 'args', doc: 'constructor arguments for T' }], returns: 'T& (C++17) — reference to the new element', doc: 'Construct an element in place at the end: `v.emplace_back(a, b)` for `vector<pair<int,int>>`. Note brace lists need `push_back({a, b})`.', example: 'vector<pair<int, int>> edges;\nedges.emplace_back(u, w);' },
  { name: 'pop_back', owner: 'vector', kind: 'method', sig: 'void vector<T>::pop_back()', returns: 'void', doc: 'Remove the last element, **O(1)**. Returns void — read `back()` first. UB on an empty vector.', example: 'v.pop_back();  // UB if v is empty' },
  { name: 'back', owner: 'vector', kind: 'method', sig: 'T& vector<T>::back()', returns: 'T& — the last element (UB if empty)', doc: 'Reference to the last element. UB if empty.', example: 'int last = v.back();' },
  { name: 'front', owner: 'vector', kind: 'method', sig: 'T& vector<T>::front()', returns: 'T& — the first element (UB if empty)', doc: 'Reference to the first element. UB if empty.', example: 'int first = v.front();' },
  { name: 'size', owner: 'vector', kind: 'method', sig: 'size_t vector<T>::size()', returns: 'size_t — number of elements (unsigned)', doc: 'Number of elements (unsigned!). `v.size() - 1` underflows when empty — use `(int)v.size() - 1`.', example: 'int n = (int)v.size();' },
  { name: 'empty', owner: 'vector', kind: 'method', sig: 'bool vector<T>::empty()', returns: 'bool — true if size() == 0', doc: 'True if size() == 0.', example: 'if (v.empty()) return -1;' },
  { name: 'clear', owner: 'vector', kind: 'method', sig: 'void vector<T>::clear()', returns: 'void', doc: 'Remove all elements (capacity is kept).', example: 'v.clear();  // size 0, capacity kept' },
  { name: 'insert', owner: 'vector', kind: 'method', sig: 'iterator vector<T>::insert(const_iterator pos, const T& value)', params: [{ label: 'pos', doc: 'insert before this iterator' }, { label: 'value', doc: 'element (or count+value, or a range)' }], returns: 'iterator — to the inserted element', doc: 'Insert before *pos*, **O(n)** shift. Overloads: `(pos, count, value)`, `(pos, first, last)`, `(pos, {…})`.', example: 'v.insert(v.begin() + i, x);\nv.insert(v.end(), w.begin(), w.end()); // append w' },
  { name: 'erase', owner: 'vector', kind: 'method', sig: 'iterator vector<T>::erase(const_iterator first, const_iterator last)', params: [{ label: 'first', doc: 'first element to remove' }, { label: 'last', doc: 'one past the last (omit to erase one)' }], returns: 'iterator — to the element after the last one removed', doc: 'Remove an element or range, **O(n)**; returns the iterator after the removed part. C++20: `erase(v, x)` / `erase_if(v, pred)` free functions.', example: 'v.erase(v.begin() + i);\nv.erase(unique(v.begin(), v.end()), v.end());' },
  { name: 'begin', owner: 'vector', kind: 'method', sig: 'iterator vector<T>::begin()', returns: 'iterator — to the first element', doc: 'Iterator to the first element; pair with `end()` for algorithms: `sort(v.begin(), v.end())`.', example: 'sort(v.begin(), v.end());' },
  { name: 'end', owner: 'vector', kind: 'method', sig: 'iterator vector<T>::end()', returns: 'iterator — one past the last element (never dereference)', doc: 'Iterator **one past** the last element — don\'t dereference.', example: 'bool has = find(v.begin(), v.end(), x) != v.end();' },
  { name: 'rbegin', owner: 'vector', kind: 'method', sig: 'reverse_iterator vector<T>::rbegin()', returns: 'reverse_iterator — to the last element', doc: 'Reverse iterator to the last element. `sort(v.rbegin(), v.rend())` sorts descending.', example: 'sort(v.rbegin(), v.rend());  // descending' },
  { name: 'rend', owner: 'vector', kind: 'method', sig: 'reverse_iterator vector<T>::rend()', returns: 'reverse_iterator — one before the first element', doc: 'Reverse iterator one before the first element.', example: 'vector<int> r(v.rbegin(), v.rend());  // reversed copy' },
  { name: 'resize', owner: 'vector', kind: 'method', sig: 'void vector<T>::resize(size_t n, const T& value = T())', params: [{ label: 'n', doc: 'new size' }, { label: 'value', doc: 'value for new elements' }], returns: 'void', doc: 'Change size; new elements get *value*, extra ones are destroyed.', example: 'v.resize(n, -1);' },
  { name: 'reserve', owner: 'vector', kind: 'method', sig: 'void vector<T>::reserve(size_t n)', params: [{ label: 'n', doc: 'capacity' }], returns: 'void', doc: 'Pre-allocate capacity without changing size (avoids reallocations). Doesn\'t make `v[i]` valid — use `resize` for that.', example: 'v.reserve(n);\nfor (int i = 0; i < n; i++) v.push_back(i);' },
  { name: 'assign', owner: 'vector', kind: 'method', sig: 'void vector<T>::assign(size_t n, const T& value)', params: [{ label: 'n', doc: 'new size' }, { label: 'value', doc: 'fill value' }], returns: 'void', doc: 'Replace contents with *n* copies of *value* (or a range `assign(first, last)`). Handy to reset a global between test cases.', example: 'dist.assign(n, INT_MAX);' },
  { name: 'at', owner: 'vector', kind: 'method', sig: 'T& vector<T>::at(size_t i)', params: [{ label: 'i', doc: 'index' }], returns: 'T& — element i; throws std::out_of_range if out of bounds', doc: 'Bounds-checked access; throws `std::out_of_range` instead of UB.', example: 'int x = v.at(i);  // throws if i >= size()' },
  { name: 'operator[]', owner: 'vector', kind: 'method', sig: 'T& vector<T>::operator[](size_t i)', params: [{ label: 'i', doc: 'index' }], returns: 'T& — element i (no bounds check)', doc: 'Unchecked **O(1)** access — out-of-range is UB (often a silent wrong answer or crash).', example: 'v[i] += 1;' },
  { name: 'data', owner: 'vector', kind: 'method', sig: 'T* vector<T>::data()', returns: 'T* — pointer to the contiguous storage', doc: 'Pointer to the underlying contiguous array.', example: 'memset(v.data(), 0, v.size() * sizeof(int));' },
  { name: 'swap', owner: 'vector', kind: 'method', sig: 'void vector<T>::swap(vector<T>& other)', params: [{ label: 'other', doc: 'vector to swap with' }], returns: 'void', doc: '**O(1)** swap of contents — useful for rolling DP rows: `prev.swap(cur)`.', example: 'cur.swap(nxt);  // O(1), e.g. rolling DP rows' },

  // ───────────── string ─────────────
  { name: 'size', owner: 'string', kind: 'method', sig: 'size_t string::size()', returns: 'size_t — number of characters (unsigned)', doc: 'Length in bytes, **O(1)** (same as `length()`). Unsigned — beware `s.size() - 1` when empty.', example: 'int n = (int)s.size();' },
  { name: 'length', owner: 'string', kind: 'method', sig: 'size_t string::length()', returns: 'size_t — number of characters (same as size())', doc: 'Same as `size()`.', example: 'int len = (int)s.length();' },
  { name: 'empty', owner: 'string', kind: 'method', sig: 'bool string::empty()', returns: 'bool — true if the string has no characters', doc: 'True if the string has no characters.', example: 'if (s.empty()) return "";' },
  { name: 'substr', owner: 'string', kind: 'method', sig: 'string string::substr(size_t pos = 0, size_t len = npos)', params: [{ label: 'pos', doc: 'start index' }, { label: 'len', doc: 'max length (not end index!)' }], returns: 'string — copy of [pos, pos + len), len clipped to the end', doc: 'Copy of a substring — **O(len)**. Second argument is a *length*, unlike Java/Python. Use `string_view` to avoid copies.', example: 's.substr(i, j - i) // chars [i, j)' },
  { name: 'find', owner: 'string', kind: 'method', sig: 'size_t string::find(const string& str, size_t pos = 0)', params: [{ label: 'str', doc: 'substring or char to find' }, { label: 'pos', doc: 'start position' }], returns: 'size_t — index of the first match, or string::npos', doc: 'Index of the first occurrence, or `string::npos` if absent — always compare with `npos`, not -1/false.', example: 'if (s.find("ab") != string::npos) { }' },
  { name: 'rfind', owner: 'string', kind: 'method', sig: 'size_t string::rfind(const string& str, size_t pos = npos)', params: [{ label: 'str', doc: 'substring or char' }, { label: 'pos', doc: 'search at or before this index' }], returns: 'size_t — index of the last match starting at or before pos, or npos', doc: 'Index of the last occurrence, or `npos`.', example: 'size_t dot = name.rfind(\'.\');\nstring ext = name.substr(dot + 1);' },
  { name: 'find_first_of', owner: 'string', kind: 'method', sig: 'size_t string::find_first_of(const string& chars, size_t pos = 0)', params: [{ label: 'chars', doc: 'set of characters' }, { label: 'pos', doc: 'start position' }], returns: 'size_t — index of the first char that is in chars, or npos', doc: 'Index of the first char that is any of *chars*, or `npos`. See also `find_first_not_of` (trimming).', example: 'size_t p = s.find_first_of("aeiou");' },
  { name: 'npos', owner: 'string', kind: 'constant', sig: 'static const size_t string::npos = -1', doc: '"Not found" sentinel returned by `find`; also means "to the end" in `substr`.', example: 'if (s.find("ab") == string::npos) cout << "absent";' },
  { name: 'push_back', owner: 'string', kind: 'method', sig: 'void string::push_back(char c)', params: [{ label: 'c', doc: 'character to append' }], returns: 'void', doc: 'Append one char, amortised **O(1)** (same as `s += c`).', example: 's.push_back(\'a\');' },
  { name: 'pop_back', owner: 'string', kind: 'method', sig: 'void string::pop_back()', returns: 'void', doc: 'Remove the last char. UB if empty.', example: 's.pop_back();  // UB if empty' },
  { name: 'append', owner: 'string', kind: 'method', sig: 'string& string::append(const string& str)', params: [{ label: 'str', doc: 'text to append (or count, char)' }], returns: 'string& — *this', doc: 'Append text; `append(n, c)` appends *n* copies of *c*.', example: 's.append("xyz");' },
  { name: 'operator+=', owner: 'string', kind: 'method', sig: 'string& string::operator+=(const string& str)', params: [{ label: 'str', doc: 'string or char' }], returns: 'string& — *this', doc: 'Append in place, amortised **O(len(str))**. Prefer over `s = s + t`, which builds a new string each time.', example: 'res += to_string(x);\nres += \',\';' },
  { name: 'insert', owner: 'string', kind: 'method', sig: 'string& string::insert(size_t pos, const string& str)', params: [{ label: 'pos', doc: 'index' }, { label: 'str', doc: 'text to insert' }], returns: 'string& — *this', doc: 'Insert at *pos*, **O(n)**. `insert(0, 1, c)` prepends a char — building by prepending is quadratic; append then `reverse`.', example: 's.insert(0, "0");  // prepend, O(n)' },
  { name: 'erase', owner: 'string', kind: 'method', sig: 'string& string::erase(size_t pos = 0, size_t len = npos)', params: [{ label: 'pos', doc: 'start index' }, { label: 'len', doc: 'chars to remove' }], returns: 'string& — *this', doc: 'Remove *len* chars from *pos*, **O(n)**. Gotcha: `s.erase(i)` removes everything from i — use `s.erase(i, 1)` for one char.', example: 's.erase(0, 2);  // drop the first two chars' },
  { name: 'replace', owner: 'string', kind: 'method', sig: 'string& string::replace(size_t pos, size_t len, const string& str)', params: [{ label: 'pos', doc: 'start index' }, { label: 'len', doc: 'chars to replace' }, { label: 'str', doc: 'replacement' }], returns: 'string& — *this', doc: 'Replace a range with *str*. To replace all of one char, use `std::replace(s.begin(), s.end(), a, b)`.', example: 's.replace(0, 3, "abc");' },
  { name: 'compare', owner: 'string', kind: 'method', sig: 'int string::compare(const string& str)', params: [{ label: 'str', doc: 'other string' }], returns: 'int — negative, 0 or positive (lexicographic order)', doc: '<0, 0, >0 three-way compare. Usually `==` / `<` are clearer.', example: 'if (a.compare(b) < 0) cout << "a sorts first";' },
  { name: 'c_str', owner: 'string', kind: 'method', sig: 'const char* string::c_str()', returns: 'const char* — null-terminated buffer, invalidated when s is modified', doc: 'Null-terminated C string view, for `printf("%s", s.c_str())`.', example: 'printf("%s\\n", s.c_str());' },
  { name: 'back', owner: 'string', kind: 'method', sig: 'char& string::back()', returns: 'char& — the last character (UB if empty)', doc: 'Last character. UB if empty.', example: 'if (!s.empty() && s.back() == \' \') s.pop_back();' },
  { name: 'front', owner: 'string', kind: 'method', sig: 'char& string::front()', returns: 'char& — the first character (UB if empty)', doc: 'First character. UB if empty.', example: 'char first = s.front();' },
  { name: 'at', owner: 'string', kind: 'method', sig: 'char& string::at(size_t i)', params: [{ label: 'i', doc: 'index' }], returns: 'char& — character i; throws std::out_of_range if out of bounds', doc: 'Bounds-checked char access (throws on out of range).', example: 'char c = s.at(i);' },
  { name: 'operator[]', owner: 'string', kind: 'method', sig: 'char& string::operator[](size_t i)', params: [{ label: 'i', doc: 'index' }], returns: 'char& — character i (no bounds check)', doc: 'Unchecked **O(1)** char access; `s[s.size()]` is `\'\\0\'`.', example: 's[0] = toupper(s[0]);' },
  { name: 'clear', owner: 'string', kind: 'method', sig: 'void string::clear()', returns: 'void', doc: 'Make the string empty.', example: 's.clear();' },
  { name: 'resize', owner: 'string', kind: 'method', sig: 'void string::resize(size_t n, char c = \'\\0\')', params: [{ label: 'n', doc: 'new length' }, { label: 'c', doc: 'fill char' }], returns: 'void', doc: 'Truncate or extend to *n* chars.', example: 's.resize(5, \'0\');' },
  { name: 'begin', owner: 'string', kind: 'method', sig: 'iterator string::begin()', returns: 'iterator — to the first character', doc: 'Iterator to the first char: `sort(s.begin(), s.end())`, `reverse(s.begin(), s.end())`.', example: 'reverse(s.begin(), s.end());' },
  { name: 'end', owner: 'string', kind: 'method', sig: 'iterator string::end()', returns: 'iterator — one past the last character', doc: 'Iterator one past the last char.', example: 'sort(s.begin(), s.end());' },
  { name: 'starts_with', owner: 'string', kind: 'method', sig: 'bool string::starts_with(string_view prefix)', params: [{ label: 'prefix', doc: 'prefix (or char)' }], returns: 'bool — true if the string begins with prefix (C++20)', doc: 'C++20 prefix test.', example: 'if (url.starts_with("https://")) secure = true;' },
  { name: 'ends_with', owner: 'string', kind: 'method', sig: 'bool string::ends_with(string_view suffix)', params: [{ label: 'suffix', doc: 'suffix (or char)' }], returns: 'bool — true if the string ends with suffix (C++20)', doc: 'C++20 suffix test.', example: 'bool png = file.ends_with(".png");' },

  // ───────────── unordered_map ─────────────
  { name: 'operator[]', owner: 'unordered_map', kind: 'method', sig: 'V& unordered_map<K,V>::operator[](const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'V& — the mapped value; inserts V{} first if key is absent', doc: 'Access, **inserting a default value** if *key* is missing — so `if (m[k])` grows the map. Use `count`/`contains`/`find` to test existence.', example: 'cnt[x]++; // missing → 0 then 1' },
  { name: 'at', owner: 'unordered_map', kind: 'method', sig: 'V& unordered_map<K,V>::at(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'V& — the mapped value; throws std::out_of_range if key is absent', doc: 'Access without inserting; throws `out_of_range` if missing. Works on const maps.', example: 'int v = m.at(key);' },
  { name: 'find', owner: 'unordered_map', kind: 'method', sig: 'iterator unordered_map<K,V>::find(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'iterator — to the element, or end() if absent', doc: 'Iterator to the entry or `end()`. One lookup gives both existence and value (`it->second`).', example: 'if (auto it = m.find(k); it != m.end()) use(it->second);' },
  { name: 'count', owner: 'unordered_map', kind: 'method', sig: 'size_t unordered_map<K,V>::count(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'size_t — 1 if present, else 0', doc: '1 if present, 0 otherwise — existence test that doesn\'t insert.', example: 'if (m.count(key)) cnt++;' },
  { name: 'contains', owner: 'unordered_map', kind: 'method', sig: 'bool unordered_map<K,V>::contains(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'bool — true if present (C++20)', doc: 'C++20 existence test.', example: 'if (m.contains(key)) cnt++;' },
  { name: 'insert', owner: 'unordered_map', kind: 'method', sig: 'pair<iterator, bool> unordered_map<K,V>::insert(const pair<K,V>& kv)', params: [{ label: 'kv', doc: '{key, value}' }], returns: 'pair<iterator, bool> — iterator to the element; bool is false if the key already existed (value not overwritten)', doc: 'Insert if the key is absent (does **not** overwrite); `.second` tells whether it inserted.', example: 'm.insert({key, 1});  // no-op if key exists' },
  { name: 'emplace', owner: 'unordered_map', kind: 'method', sig: 'pair<iterator, bool> unordered_map<K,V>::emplace(Args&&... args)', params: [{ label: 'args', doc: 'key, value' }], returns: 'pair<iterator, bool> — iterator to the element; bool is false if the key already existed', doc: 'Construct in place if key absent; doesn\'t overwrite.', example: 'm.emplace(key, 1);' },
  { name: 'erase', owner: 'unordered_map', kind: 'method', sig: 'size_t unordered_map<K,V>::erase(const K& key)', params: [{ label: 'key', doc: 'key (or iterator)' }], returns: 'size_t — number of elements removed (0 or 1)', doc: 'Remove by key (returns count removed) or by iterator. Common in sliding windows: erase when count drops to 0.', example: 'm.erase(key);' },
  { name: 'size', owner: 'unordered_map', kind: 'method', sig: 'size_t unordered_map<K,V>::size()', returns: 'size_t — number of key-value pairs', doc: 'Number of entries (distinct keys).', example: 'int distinct = (int)m.size();' },
  { name: 'empty', owner: 'unordered_map', kind: 'method', sig: 'bool unordered_map<K,V>::empty()', returns: 'bool — true if size() == 0', doc: 'True if no entries.', example: 'if (m.empty()) return 0;' },
  { name: 'clear', owner: 'unordered_map', kind: 'method', sig: 'void unordered_map<K,V>::clear()', returns: 'void', doc: 'Remove all entries.', example: 'm.clear();' },
  { name: 'begin', owner: 'unordered_map', kind: 'method', sig: 'iterator unordered_map<K,V>::begin()', returns: 'iterator — to the first element (unspecified order)', doc: 'Iterator over `pair<const K, V>` entries in unspecified order. Usually `for (auto& [k, v] : m)`.', example: 'for (auto it = m.begin(); it != m.end(); ++it) cout << it->first;' },
  { name: 'end', owner: 'unordered_map', kind: 'method', sig: 'iterator unordered_map<K,V>::end()', returns: 'iterator — past-the-end sentinel (never dereference)', doc: 'Past-the-end iterator; `find` returns it when missing.', example: 'if (m.find(key) == m.end()) m[key] = 0;' },
  { name: 'reserve', owner: 'unordered_map', kind: 'method', sig: 'void unordered_map<K,V>::reserve(size_t n)', params: [{ label: 'n', doc: 'expected element count' }], returns: 'void', doc: 'Pre-size buckets to avoid rehashing — a cheap speedup for big maps.', example: 'unordered_map<int, int> m;\nm.reserve(1 << 20);' },

  // ───────────── map ─────────────
  { name: 'operator[]', owner: 'map', kind: 'method', sig: 'V& map<K,V>::operator[](const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'V& — the mapped value; inserts V{} first if key is absent', doc: 'Access, inserting a default if missing. **O(log n)**.', example: 'map<string, int> freq;\nfor (auto& w : words) freq[w]++;' },
  { name: 'at', owner: 'map', kind: 'method', sig: 'V& map<K,V>::at(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'V& — the mapped value; throws std::out_of_range if key is absent', doc: 'Access without inserting; throws if missing.', example: 'int v = m.at(key);' },
  { name: 'find', owner: 'map', kind: 'method', sig: 'iterator map<K,V>::find(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'iterator — to the element, or end() if absent', doc: 'Iterator to the entry or `end()`, **O(log n)**.', example: 'auto it = m.find(key);\nif (it != m.end()) use(it->second);' },
  { name: 'count', owner: 'map', kind: 'method', sig: 'size_t map<K,V>::count(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'size_t — 1 if present, else 0', doc: '1 if present else 0.', example: 'if (m.count(key)) cnt++;' },
  { name: 'contains', owner: 'map', kind: 'method', sig: 'bool map<K,V>::contains(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'bool — true if present (C++20)', doc: 'C++20 existence test.', example: 'if (m.contains(key)) cnt++;' },
  { name: 'insert', owner: 'map', kind: 'method', sig: 'pair<iterator, bool> map<K,V>::insert(const pair<K,V>& kv)', params: [{ label: 'kv', doc: '{key, value}' }], returns: 'pair<iterator, bool> — iterator to the element; bool is false if the key already existed (value not overwritten)', doc: 'Insert if absent (no overwrite). `insert_or_assign` overwrites.', example: 'm.insert({key, 1});  // no-op if key exists' },
  { name: 'emplace', owner: 'map', kind: 'method', sig: 'pair<iterator, bool> map<K,V>::emplace(Args&&... args)', params: [{ label: 'args', doc: 'key, value' }], returns: 'pair<iterator, bool> — iterator to the element; bool is false if the key already existed', doc: 'Construct in place if key absent.', example: 'm.emplace(key, 1);' },
  { name: 'erase', owner: 'map', kind: 'method', sig: 'size_t map<K,V>::erase(const K& key)', params: [{ label: 'key', doc: 'key (or iterator)' }], returns: 'size_t — number of elements removed (0 or 1)', doc: 'Remove by key or iterator, **O(log n)**. Erasing via iterator returns the next iterator.', example: 'm.erase(key);' },
  { name: 'lower_bound', owner: 'map', kind: 'method', sig: 'iterator map<K,V>::lower_bound(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'iterator — first element with key >= the argument, or end()', doc: 'First entry with key **≥** *key*, **O(log n)**. Use the member, not `std::lower_bound` (which is O(n) on map iterators).', example: 'auto it = m.lower_bound(x);\nif (it != m.end()) cout << it->first;' },
  { name: 'upper_bound', owner: 'map', kind: 'method', sig: 'iterator map<K,V>::upper_bound(const K& key)', params: [{ label: 'key', doc: 'key' }], returns: 'iterator — first element with key > the argument, or end()', doc: 'First entry with key **>** *key*. Largest key ≤ x: `prev(m.upper_bound(x))` (check it != begin first).', example: 'auto it = m.upper_bound(t);\nif (it != m.begin()) cout << prev(it)->second;  // last key <= t' },
  { name: 'begin', owner: 'map', kind: 'method', sig: 'iterator map<K,V>::begin()', returns: 'iterator — to the smallest element', doc: 'Iterator to the smallest key: `m.begin()->first`.', example: 'int smallest = m.begin()->first;' },
  { name: 'end', owner: 'map', kind: 'method', sig: 'iterator map<K,V>::end()', returns: 'iterator — past-the-end sentinel (never dereference)', doc: 'Past-the-end iterator. Largest entry is `prev(m.end())` or `m.rbegin()`.', example: 'if (m.find(key) == m.end()) m[key] = 0;' },
  { name: 'rbegin', owner: 'map', kind: 'method', sig: 'reverse_iterator map<K,V>::rbegin()', returns: 'reverse_iterator — to the largest element', doc: 'Reverse iterator to the largest key.', example: 'int largest = m.rbegin()->first;' },
  { name: 'size', owner: 'map', kind: 'method', sig: 'size_t map<K,V>::size()', returns: 'size_t — number of key-value pairs', doc: 'Number of entries.', example: 'int distinct = (int)m.size();' },
  { name: 'empty', owner: 'map', kind: 'method', sig: 'bool map<K,V>::empty()', returns: 'bool — true if size() == 0', doc: 'True if no entries.', example: 'if (m.empty()) return 0;' },
  { name: 'clear', owner: 'map', kind: 'method', sig: 'void map<K,V>::clear()', returns: 'void', doc: 'Remove all entries.', example: 'm.clear();' },

  // ───────────── unordered_set ─────────────
  { name: 'insert', owner: 'unordered_set', kind: 'method', sig: 'pair<iterator, bool> unordered_set<T>::insert(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'pair<iterator, bool> — iterator to the element; bool is true if newly inserted', doc: 'Insert if absent; `.second` is false if already present (neat duplicate check).', example: 'if (!s.insert(x).second) dup = true;' },
  { name: 'erase', owner: 'unordered_set', kind: 'method', sig: 'size_t unordered_set<T>::erase(const T& value)', params: [{ label: 'value', doc: 'element (or iterator)' }], returns: 'size_t — number of elements removed (0 or 1)', doc: 'Remove if present; returns count removed.', example: 's.erase(x);' },
  { name: 'count', owner: 'unordered_set', kind: 'method', sig: 'size_t unordered_set<T>::count(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'size_t — 1 if present, else 0', doc: '1 if present else 0, average **O(1)**.', example: 'if (s.count(x)) cnt++;' },
  { name: 'contains', owner: 'unordered_set', kind: 'method', sig: 'bool unordered_set<T>::contains(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'bool — true if present (C++20)', doc: 'C++20 membership test.', example: 'if (s.contains(x)) cnt++;' },
  { name: 'find', owner: 'unordered_set', kind: 'method', sig: 'iterator unordered_set<T>::find(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'iterator — to the element, or end() if absent', doc: 'Iterator to the element or `end()`.', example: 'if (s.find(x) != s.end()) return true;' },
  { name: 'size', owner: 'unordered_set', kind: 'method', sig: 'size_t unordered_set<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements.', example: 'int distinct = (int)s.size();' },
  { name: 'empty', owner: 'unordered_set', kind: 'method', sig: 'bool unordered_set<T>::empty()', returns: 'bool — true if size() == 0', doc: 'True if no elements.', example: 'if (s.empty()) return 0;' },
  { name: 'clear', owner: 'unordered_set', kind: 'method', sig: 'void unordered_set<T>::clear()', returns: 'void', doc: 'Remove all elements.', example: 's.clear();' },

  // ───────────── set ─────────────
  { name: 'insert', owner: 'set', kind: 'method', sig: 'pair<iterator, bool> set<T>::insert(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'pair<iterator, bool> — iterator to the element; bool is true if newly inserted', doc: 'Insert if absent, **O(log n)**; `.second` false if it was already there.', example: 'if (!s.insert(x).second) dup = true;' },
  { name: 'erase', owner: 'set', kind: 'method', sig: 'size_t set<T>::erase(const T& value)', params: [{ label: 'value', doc: 'element (or iterator)' }], returns: 'size_t — number of elements removed (0 or 1)', doc: 'Remove by value or iterator, **O(log n)**.', example: 's.erase(x);' },
  { name: 'count', owner: 'set', kind: 'method', sig: 'size_t set<T>::count(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'size_t — 1 if present, else 0', doc: '1 if present else 0.', example: 'if (s.count(x)) cnt++;' },
  { name: 'contains', owner: 'set', kind: 'method', sig: 'bool set<T>::contains(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'bool — true if present (C++20)', doc: 'C++20 membership test.', example: 'if (s.contains(x)) cnt++;' },
  { name: 'find', owner: 'set', kind: 'method', sig: 'iterator set<T>::find(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'iterator — to the element, or end() if absent', doc: 'Iterator to the element or `end()`.', example: 'if (s.find(x) != s.end()) return true;' },
  { name: 'lower_bound', owner: 'set', kind: 'method', sig: 'iterator set<T>::lower_bound(const T& value)', params: [{ label: 'value', doc: 'key' }], returns: 'iterator — first element with value >= the argument, or end()', doc: 'First element **≥** value, **O(log n)**. Always use the member — `std::lower_bound(s.begin(), s.end(), x)` is O(n) on set iterators.', example: 'auto it = s.lower_bound(x);\nif (it != s.end()) best = *it;  // smallest >= x' },
  { name: 'upper_bound', owner: 'set', kind: 'method', sig: 'iterator set<T>::upper_bound(const T& value)', params: [{ label: 'value', doc: 'key' }], returns: 'iterator — first element with value > the argument, or end()', doc: 'First element **>** value. Predecessor ≤ x: `prev(s.upper_bound(x))` when it != begin.', example: 'auto it = s.upper_bound(x);  // first element > x' },
  { name: 'begin', owner: 'set', kind: 'method', sig: 'iterator set<T>::begin()', returns: 'iterator — to the smallest element', doc: 'Iterator to the smallest element: `*s.begin()`.', example: 'int mn = *s.begin();' },
  { name: 'end', owner: 'set', kind: 'method', sig: 'iterator set<T>::end()', returns: 'iterator — past-the-end sentinel (never dereference)', doc: 'Past-the-end iterator.', example: 'if (s.find(x) == s.end()) cnt++;' },
  { name: 'rbegin', owner: 'set', kind: 'method', sig: 'reverse_iterator set<T>::rbegin()', returns: 'reverse_iterator — to the largest element', doc: 'Reverse iterator to the largest element: `*s.rbegin()`.', example: 'int mx = *s.rbegin();' },
  { name: 'size', owner: 'set', kind: 'method', sig: 'size_t set<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements.', example: 'int distinct = (int)s.size();' },
  { name: 'empty', owner: 'set', kind: 'method', sig: 'bool set<T>::empty()', returns: 'bool — true if size() == 0', doc: 'True if no elements.', example: 'if (s.empty()) return 0;' },
  { name: 'clear', owner: 'set', kind: 'method', sig: 'void set<T>::clear()', returns: 'void', doc: 'Remove all elements.', example: 's.clear();' },

  // ───────────── multiset ─────────────
  { name: 'insert', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::insert(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'iterator — to the inserted element (always inserts)', doc: 'Always inserts (duplicates allowed), **O(log n)**.', example: 'ms.insert(x);' },
  { name: 'erase', owner: 'multiset', kind: 'method', sig: 'size_t multiset<T>::erase(const T& value)', params: [{ label: 'value', doc: 'value — or an iterator' }], returns: 'size_t — number of copies removed (all of them!)', doc: '**Gotcha:** erasing by value removes **every** copy. Remove one: `ms.erase(ms.find(x))` (check find != end).', example: 'ms.erase(ms.find(x));  // remove ONE copy (x must be present)' },
  { name: 'count', owner: 'multiset', kind: 'method', sig: 'size_t multiset<T>::count(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'size_t — number of copies (O(log n + count))', doc: 'Number of copies — **O(log n + count)**.', example: 'int c = (int)ms.count(x);' },
  { name: 'find', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::find(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'iterator — to some copy of value, or end()', doc: 'Iterator to one copy, or `end()`.', example: 'auto it = ms.find(x);\nif (it != ms.end()) ms.erase(it);' },
  { name: 'lower_bound', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::lower_bound(const T& value)', params: [{ label: 'value', doc: 'key' }], returns: 'iterator — first element >= value, or end()', doc: 'First element ≥ value, **O(log n)**.', example: 'auto it = ms.lower_bound(x);  // first >= x' },
  { name: 'upper_bound', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::upper_bound(const T& value)', params: [{ label: 'value', doc: 'key' }], returns: 'iterator — first element > value, or end()', doc: 'First element > value.', example: 'auto it = ms.upper_bound(x);  // first > x' },
  { name: 'begin', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::begin()', returns: 'iterator — to the smallest element', doc: 'Iterator to the smallest element.', example: 'int mn = *ms.begin();' },
  { name: 'rbegin', owner: 'multiset', kind: 'method', sig: 'reverse_iterator multiset<T>::rbegin()', returns: 'reverse_iterator — to the largest element', doc: 'Reverse iterator to the largest element.', example: 'int mx = *ms.rbegin();' },
  { name: 'size', owner: 'multiset', kind: 'method', sig: 'size_t multiset<T>::size()', returns: 'size_t — number of elements, counting duplicates', doc: 'Number of elements including duplicates.', example: 'int n = (int)ms.size();' },
  { name: 'end', owner: 'multiset', kind: 'method', sig: 'iterator multiset<T>::end()', returns: 'iterator — past-the-end sentinel (never dereference)', doc: 'Compare `find` results against it; `*prev(ms.end())` is the largest element.', example: 'if (ms.find(x) != ms.end()) cnt++;' },
  { name: 'empty', owner: 'multiset', kind: 'method', sig: 'bool multiset<T>::empty()', returns: 'bool — true if no elements', doc: 'Check before `*ms.begin()` / `*ms.rbegin()`, which are UB on an empty multiset.', example: 'if (!ms.empty()) mx = *ms.rbegin();' },
  { name: 'clear', owner: 'multiset', kind: 'method', sig: 'void multiset<T>::clear()', returns: 'void', doc: 'Remove all elements. **O(n)**.', example: 'ms.clear();' },
  { name: 'contains', owner: 'multiset', kind: 'method', sig: 'bool multiset<T>::contains(const T& value)', params: [{ label: 'value', doc: 'value to look for' }], returns: 'bool — true if at least one copy is present (C++20)', doc: 'Membership test in **O(log n)**; cheaper than `count`, which is O(log n + copies).', example: 'if (ms.contains(x)) ms.erase(ms.find(x));' },

  // ───────────── queue ─────────────
  { name: 'push', owner: 'queue', kind: 'method', sig: 'void queue<T>::push(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'void', doc: 'Enqueue at the back, **O(1)**.', example: 'q.push(start);' },
  { name: 'emplace', owner: 'queue', kind: 'method', sig: 'void queue<T>::emplace(Args&&... args)', params: [{ label: 'args', doc: 'constructor args' }], returns: 'void', doc: 'Construct at the back in place: `q.emplace(r, c)` for `queue<pair<int,int>>`.', example: 'queue<pair<int, int>> q;\nq.emplace(r, c);' },
  { name: 'pop', owner: 'queue', kind: 'method', sig: 'void queue<T>::pop()', returns: 'void (does not return the element)', doc: 'Remove the front element. Returns **void** — read `front()` first. UB if empty.', example: 'int u = q.front(); q.pop();' },
  { name: 'front', owner: 'queue', kind: 'method', sig: 'T& queue<T>::front()', returns: 'T& — the oldest element (UB if empty)', doc: 'Next element to be dequeued.', example: 'int u = q.front();' },
  { name: 'back', owner: 'queue', kind: 'method', sig: 'T& queue<T>::back()', returns: 'T& — the most recently pushed element (UB if empty)', doc: 'Most recently pushed element.', example: 'int newest = q.back();' },
  { name: 'size', owner: 'queue', kind: 'method', sig: 'size_t queue<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements. Snapshot it for level-order BFS: `for (int k = q.size(); k--; )`.', example: 'for (int sz = (int)q.size(); sz > 0; sz--) { /* one BFS level */ }' },
  { name: 'empty', owner: 'queue', kind: 'method', sig: 'bool queue<T>::empty()', returns: 'bool — true if no elements', doc: 'True if empty.', example: 'while (!q.empty()) {\n  int u = q.front(); q.pop();\n}' },

  // ───────────── priority_queue ─────────────
  { name: 'push', owner: 'priority_queue', kind: 'method', sig: 'void priority_queue<T>::push(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'void', doc: 'Insert, **O(log n)**.', example: 'pq.push(x);  // O(log n)' },
  { name: 'emplace', owner: 'priority_queue', kind: 'method', sig: 'void priority_queue<T>::emplace(Args&&... args)', params: [{ label: 'args', doc: 'constructor args' }], returns: 'void', doc: 'Construct in place, **O(log n)**.', example: 'pq.emplace(dist, node);' },
  { name: 'pop', owner: 'priority_queue', kind: 'method', sig: 'void priority_queue<T>::pop()', returns: 'void (does not return the element)', doc: 'Remove the top element, **O(log n)**. Returns void — read `top()` first.', example: 'auto [d, u] = pq.top(); pq.pop();' },
  { name: 'top', owner: 'priority_queue', kind: 'method', sig: 'const T& priority_queue<T>::top()', returns: 'const T& — the largest element (smallest with greater<>); UB if empty', doc: 'Largest element (smallest with `greater<>`), **O(1)**. UB if empty.', example: 'int best = pq.top();' },
  { name: 'size', owner: 'priority_queue', kind: 'method', sig: 'size_t priority_queue<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements. Keep-k-largest idiom: min-heap, pop when size() > k.', example: 'if ((int)pq.size() > k) pq.pop();' },
  { name: 'empty', owner: 'priority_queue', kind: 'method', sig: 'bool priority_queue<T>::empty()', returns: 'bool — true if no elements', doc: 'True if empty.', example: 'while (!pq.empty()) { auto cur = pq.top(); pq.pop(); }' },

  // ───────────── stack ─────────────
  { name: 'push', owner: 'stack', kind: 'method', sig: 'void stack<T>::push(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'void', doc: 'Push on top, **O(1)**.', example: 'st.push(i);' },
  { name: 'emplace', owner: 'stack', kind: 'method', sig: 'void stack<T>::emplace(Args&&... args)', params: [{ label: 'args', doc: 'constructor args' }], returns: 'void', doc: 'Construct on top in place.', example: 'stack<pair<int, int>> st;\nst.emplace(i, h);' },
  { name: 'pop', owner: 'stack', kind: 'method', sig: 'void stack<T>::pop()', returns: 'void (does not return the element)', doc: 'Remove the top. Returns void — read `top()` first. UB if empty.', example: 'int t = st.top(); st.pop();' },
  { name: 'top', owner: 'stack', kind: 'method', sig: 'T& stack<T>::top()', returns: 'T& — the most recently pushed element (UB if empty)', doc: 'Top element. Check `empty()` first (e.g. bracket matching).', example: 'while (!st.empty() && st.top() < x) st.pop();' },
  { name: 'size', owner: 'stack', kind: 'method', sig: 'size_t stack<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements.', example: 'int depth = (int)st.size();' },
  { name: 'empty', owner: 'stack', kind: 'method', sig: 'bool stack<T>::empty()', returns: 'bool — true if no elements', doc: 'True if empty.', example: 'if (st.empty() || st.top() != \'(\') return false;' },

  // ───────────── deque ─────────────
  { name: 'push_back', owner: 'deque', kind: 'method', sig: 'void deque<T>::push_back(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'void', doc: 'Append at the back, **O(1)**.', example: 'dq.push_back(i);' },
  { name: 'push_front', owner: 'deque', kind: 'method', sig: 'void deque<T>::push_front(const T& value)', params: [{ label: 'value', doc: 'element' }], returns: 'void', doc: 'Prepend at the front, **O(1)** (0-1 BFS pushes weight-0 edges here).', example: 'dq.push_front(i);  // O(1), e.g. 0-1 BFS' },
  { name: 'pop_back', owner: 'deque', kind: 'method', sig: 'void deque<T>::pop_back()', returns: 'void', doc: 'Remove the back element. Returns void.', example: 'while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();' },
  { name: 'pop_front', owner: 'deque', kind: 'method', sig: 'void deque<T>::pop_front()', returns: 'void', doc: 'Remove the front element. Returns void.', example: 'if (dq.front() <= i - k) dq.pop_front();' },
  { name: 'front', owner: 'deque', kind: 'method', sig: 'T& deque<T>::front()', returns: 'T& — the first element (UB if empty)', doc: 'First element (monotonic queue: current window max/min).', example: 'int best = a[dq.front()];' },
  { name: 'back', owner: 'deque', kind: 'method', sig: 'T& deque<T>::back()', returns: 'T& — the last element (UB if empty)', doc: 'Last element.', example: 'int last = dq.back();' },
  { name: 'size', owner: 'deque', kind: 'method', sig: 'size_t deque<T>::size()', returns: 'size_t — number of elements', doc: 'Number of elements.', example: 'int n = (int)dq.size();' },
  { name: 'empty', owner: 'deque', kind: 'method', sig: 'bool deque<T>::empty()', returns: 'bool — true if no elements', doc: 'True if empty.', example: 'if (dq.empty()) return -1;' },
  { name: 'operator[]', owner: 'deque', kind: 'method', sig: 'T& deque<T>::operator[](size_t i)', params: [{ label: 'i', doc: 'index' }], returns: 'T& — element i (no bounds check)', doc: 'Unchecked **O(1)** random access.', example: 'int x = dq[i];  // O(1)' },
  { name: 'clear', owner: 'deque', kind: 'method', sig: 'void deque<T>::clear()', returns: 'void', doc: 'Remove all elements. **O(n)**.', example: 'dq.clear();' },
  { name: 'push_back', owner: 'list', kind: 'method', sig: 'void list<T>::push_back(const T& value)', params: [{ label: 'value', doc: 'element to append' }], returns: 'void', doc: 'Append at the back. **O(1)**.', example: 'l.push_back(x);' },
  { name: 'push_front', owner: 'list', kind: 'method', sig: 'void list<T>::push_front(const T& value)', params: [{ label: 'value', doc: 'element to prepend' }], returns: 'void', doc: 'Prepend at the front. **O(1)**.', example: 'l.push_front(x);' },
  { name: 'pop_back', owner: 'list', kind: 'method', sig: 'void list<T>::pop_back()', returns: 'void', doc: 'Remove the last element. **O(1)**; UB if empty.', example: 'l.pop_back();' },
  { name: 'pop_front', owner: 'list', kind: 'method', sig: 'void list<T>::pop_front()', returns: 'void', doc: 'Remove the first element. **O(1)**; UB if empty.', example: 'l.pop_front();' },
  { name: 'front', owner: 'list', kind: 'method', sig: 'T& list<T>::front()', returns: 'T& — the first element (UB if empty)', doc: 'Access the first element.', example: 'int first = l.front();' },
  { name: 'back', owner: 'list', kind: 'method', sig: 'T& list<T>::back()', returns: 'T& — the last element (UB if empty)', doc: 'Access the last element (e.g. the least-recently-used key in an LRU cache).', example: 'int lru = l.back();' },
  { name: 'size', owner: 'list', kind: 'method', sig: 'size_t list<T>::size()', returns: 'size_t — number of elements', doc: '**O(1)** since C++11.', example: 'if ((int)l.size() > cap) l.pop_back();' },
  { name: 'empty', owner: 'list', kind: 'method', sig: 'bool list<T>::empty()', returns: 'bool — true if no elements', doc: 'Check before `front()`/`back()`.', example: 'if (l.empty()) return -1;' },
  { name: 'begin', owner: 'list', kind: 'method', sig: 'iterator list<T>::begin()', returns: 'iterator — to the first element', doc: 'Bidirectional iterator: supports `++`/`--` but not `+ k` (use `next(it, k)`, **O(k)**).', example: 'auto it = l.begin();\nint first = *it;' },
  { name: 'end', owner: 'list', kind: 'method', sig: 'iterator list<T>::end()', returns: 'iterator — past-the-end sentinel (never dereference)', doc: 'One past the last element; `prev(l.end())` is the last element.', example: 'for (auto it = l.begin(); it != l.end(); ++it) cout << *it;' },
  { name: 'insert', owner: 'list', kind: 'method', sig: 'iterator list<T>::insert(const_iterator pos, const T& value)', params: [{ label: 'pos', doc: 'insert before this position' }, { label: 'value', doc: 'element to insert' }], returns: 'iterator — to the inserted element', doc: 'Insert before *pos* in **O(1)**; no other iterators are invalidated.', example: 'auto it = l.insert(l.begin(), x);' },
  { name: 'erase', owner: 'list', kind: 'method', sig: 'iterator list<T>::erase(const_iterator pos)', params: [{ label: 'pos', doc: 'iterator to the element to remove' }], returns: 'iterator — to the element after the removed one', doc: 'Remove one element in **O(1)**; only iterators to that element are invalidated. Store iterators in a map for O(1) LRU removal.', example: 'l.erase(where[key]);\nwhere.erase(key);' },
  { name: 'splice', owner: 'list', kind: 'method', sig: 'void list<T>::splice(const_iterator pos, list& other, const_iterator it)', params: [{ label: 'pos', doc: 'insert before this position' }, { label: 'other', doc: 'source list (may be *this)' }, { label: 'it', doc: 'element to move' }], returns: 'void', doc: 'Move node *it* from *other* to before *pos* in **O(1)** without copying; iterators to it stay valid. The LRU "move to front" trick: `l.splice(l.begin(), l, it)`.', example: 'l.splice(l.begin(), l, where[key]);  // move to front' },

  // ───────────── pair / bitset / array ─────────────
  { name: 'first', owner: 'pair', kind: 'method', sig: 'T1 pair<T1,T2>::first', returns: 'T1 — the first member (a data field, not a function)', doc: 'First member (a data field, no parentheses). For map iterators, the key: `it->first`.', example: 'pair<int, string> p = {1, "a"};\nint k = p.first;' },
  { name: 'second', owner: 'pair', kind: 'method', sig: 'T2 pair<T1,T2>::second', returns: 'T2 — the second member (a data field, not a function)', doc: 'Second member (a data field). For map iterators, the value: `it->second`.', example: 'pair<int, string> p = {1, "a"};\nstring v = p.second;' },
  { name: 'count', owner: 'bitset', kind: 'method', sig: 'size_t bitset<N>::count()', returns: 'size_t — number of set bits', doc: 'Number of set bits.', example: 'bitset<32> b(13);\nint ones = (int)b.count();  // 3' },
  { name: 'set', owner: 'bitset', kind: 'method', sig: 'bitset<N>& bitset<N>::set(size_t pos, bool value = true)', params: [{ label: 'pos', doc: 'bit index (omit to set all)' }, { label: 'value', doc: 'bit value' }], returns: 'bitset<N>& — *this', doc: 'Set one bit (or all bits with no args).', example: 'b.set(3);  // bit 3 = 1' },
  { name: 'reset', owner: 'bitset', kind: 'method', sig: 'bitset<N>& bitset<N>::reset(size_t pos)', params: [{ label: 'pos', doc: 'bit index (omit to clear all)' }], returns: 'bitset<N>& — *this', doc: 'Clear one bit or all bits.', example: 'b.reset(3);  // bit 3 = 0' },
  { name: 'test', owner: 'bitset', kind: 'method', sig: 'bool bitset<N>::test(size_t pos)', params: [{ label: 'pos', doc: 'bit index' }], returns: 'bool — value of bit pos; throws std::out_of_range if pos >= N', doc: 'Bounds-checked bit read (`b[pos]` is unchecked).', example: 'if (b.test(i)) cnt++;' },
  { name: 'flip', owner: 'bitset', kind: 'method', sig: 'bitset<N>& bitset<N>::flip(size_t pos)', params: [{ label: 'pos', doc: 'bit index (omit to flip all)' }], returns: 'bitset<N>& — *this', doc: 'Toggle one bit or all bits.', example: 'b.flip(0);' },
  { name: 'any', owner: 'bitset', kind: 'method', sig: 'bool bitset<N>::any()', returns: 'bool — true if at least one bit is set', doc: 'True if any bit is set (`none()` for the opposite).', example: 'if (b.any()) cout << "nonzero";' },
  { name: 'fill', owner: 'array', kind: 'method', sig: 'void array<T,N>::fill(const T& value)', params: [{ label: 'value', doc: 'fill value' }], returns: 'void', doc: 'Set every element to *value*.', example: 'array<int, 26> cnt;\ncnt.fill(0);' },
  { name: 'size', owner: 'array', kind: 'method', sig: 'constexpr size_t array<T,N>::size()', returns: 'size_t — N (a compile-time constant)', doc: 'Compile-time size N.', example: 'array<int, 4> dx = {0, 1, 0, -1};\nfor (int k = 0; k < (int)dx.size(); k++) { }' },
  { name: 'operator[]', owner: 'array', kind: 'method', sig: 'T& array<T,N>::operator[](size_t i)', params: [{ label: 'i', doc: 'index in [0, N)' }], returns: 'T& — element i (no bounds check)', doc: 'Unchecked element access; use `.at(i)` for a bounds check. A local `array<int, N> a;` is uninitialised — write `array<int, N> a{};` to zero it.', example: 'array<int, 26> cnt{};\ncnt[c - \'a\']++;' },

  // ───────────── <algorithm> ─────────────
  { name: 'sort', owner: 'std', kind: 'function', sig: 'void sort(RandomIt first, RandomIt last, Compare comp = less<>())', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end (exclusive)' }, { label: 'comp', doc: 'strict weak ordering: true if a goes before b' }], returns: 'void', doc: 'Sort in place, **O(n log n)**, not stable. *comp* must be strict (`<`, never `<=` — that can crash). C++20: `ranges::sort(v)`.', example: 'sort(v.begin(), v.end());\nsort(v.begin(), v.end(), [](auto& a, auto& b) { return a[1] < b[1]; });', insert: 'sort(${1:v}.begin(), ${1:v}.end())', header: '#include <algorithm>' },
  { name: 'stable_sort', owner: 'std', kind: 'function', sig: 'void stable_sort(RandomIt first, RandomIt last, Compare comp = less<>())', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'comp', doc: 'comparator' }], returns: 'void', doc: 'Sort keeping equal elements in original order, **O(n log n)**.', example: 'stable_sort(v.begin(), v.end(), [](auto& a, auto& b) { return a.second < b.second; });', header: '#include <algorithm>' },
  { name: 'partial_sort', owner: 'std', kind: 'function', sig: 'void partial_sort(RandomIt first, RandomIt middle, RandomIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'middle', doc: 'end of the sorted prefix' }, { label: 'last', doc: 'range end' }], returns: 'void', doc: 'Make [first, middle) the smallest elements in sorted order, **O(n log k)**.', example: 'partial_sort(v.begin(), v.begin() + k, v.end());  // k smallest, sorted', header: '#include <algorithm>' },
  { name: 'nth_element', owner: 'std', kind: 'function', sig: 'void nth_element(RandomIt first, RandomIt nth, RandomIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'nth', doc: 'position to fix' }, { label: 'last', doc: 'range end' }], returns: 'void', doc: 'Quickselect: puts the element that would be at *nth* in sorted order there, smaller before, larger after. Average **O(n)** — "kth largest".', example: 'nth_element(v.begin(), v.begin() + k, v.end());\nint kth = v[k];  // k-th smallest (0-based)', header: '#include <algorithm>' },
  { name: 'reverse', owner: 'std', kind: 'function', sig: 'void reverse(BidirIt first, BidirIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }], returns: 'void', doc: 'Reverse a range in place, **O(n)**. Returns void.', example: 'reverse(s.begin(), s.end());', header: '#include <algorithm>' },
  { name: 'rotate', owner: 'std', kind: 'function', sig: 'ForwardIt rotate(ForwardIt first, ForwardIt middle, ForwardIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'middle', doc: 'element that becomes first' }, { label: 'last', doc: 'range end' }], returns: 'ForwardIt — new position of the element that was at first', doc: 'Left-rotate so *middle* becomes the first element, **O(n)**. Rotate right by k: `rotate(v.begin(), v.end() - k, v.end())`.', example: 'rotate(v.begin(), v.begin() + k, v.end());  // left-rotate by k', header: '#include <algorithm>', learn: {
    summary: "shift elements around in a circle",
    what: "std::rotate rearranges a range in place so that the element at middle becomes the first one; the elements that were before middle wrap around to the end, keeping their order. Picture the range as a ring of seats where everyone shifts toward the front until middle's occupant sits in the first seat. Ranges in C++ are given by iterators, which are like bookmarks pointing at positions in a container. It works on any sub-range, needs no extra array, and runs in linear time.",
    params: {
      first: "iterator to the start of the range, e.g. v.begin()",
      middle: "iterator to the element that should end up first, e.g. v.begin() + 3",
      last: "iterator just past the end of the range, e.g. v.end() or v.begin() + 4"
    },
    returns: "An iterator to where the original first element ended up. Often ignored.",
    example: "std::vector<char> v = {'a', 'b', 'c', 'd', 'e'};      // a list of items\n// range = first 4 items; middle = 'd', so 'd' comes first:\nstd::rotate(v.begin(), v.begin() + 3, v.begin() + 4);  // v is now d a b c e",
    watch: [
      "It shifts toward the front: the elements before middle move to the back. Decide which element you want first, then point middle at it.",
      "middle must lie between first and last; anything else is undefined behavior.",
      "Needs #include <algorithm>."
    ]
  }  },
  { name: 'min', owner: 'std', kind: 'function', sig: 'const T& min(const T& a, const T& b)  |  T min(initializer_list<T> il)', params: [{ label: 'a', doc: 'first value' }, { label: 'b', doc: 'second value' }, { label: 'il', doc: 'brace list of values' }], returns: 'const T& — the smaller argument (T by value for the initializer-list form)', doc: 'Smaller value. Both args must have the **same type** — `min(x, 0LL)` or `min<long long>(a, b)` when mixing. Many: `min({a, b, c})`.', example: 'int lo = min(a, b);\nint m3 = min({a, b, c});', header: '#include <algorithm>' },
  { name: 'max', owner: 'std', kind: 'function', sig: 'const T& max(const T& a, const T& b)  |  T max(initializer_list<T> il)', params: [{ label: 'a', doc: 'first value' }, { label: 'b', doc: 'second value' }, { label: 'il', doc: 'brace list of values' }], returns: 'const T& — the larger argument (T by value for the initializer-list form)', doc: 'Larger value. Same-type rule: `max(ans, (int)v.size())`. Several values: `max({a, b, c})`.', example: 'best = max(best, cur);\nint m = max({x, y, z});', header: '#include <algorithm>' },
  { name: 'minmax', owner: 'std', kind: 'function', sig: 'pair<const T&, const T&> minmax(const T& a, const T& b)', params: [{ label: 'a', doc: 'first value' }, { label: 'b', doc: 'second value' }], returns: 'pair<const T&, const T&> — (smaller, larger); dangles if given temporaries', doc: 'Returns `{min, max}`. Careful binding references to temporaries; `auto [lo, hi] = minmax(a, b);` with lvalues is fine.', example: 'auto [lo, hi] = minmax(a, b);', header: '#include <algorithm>' },
  { name: 'clamp', owner: 'std', kind: 'function', sig: 'const T& clamp(const T& v, const T& lo, const T& hi)', params: [{ label: 'v', doc: 'value' }, { label: 'lo', doc: 'lower bound' }, { label: 'hi', doc: 'upper bound' }], returns: 'const T& — v limited to [lo, hi]', doc: 'C++17: *v* limited to [lo, hi].', example: 'int px = clamp(v, 0, 255);', header: '#include <algorithm>', learn: {
    summary: "force a value into a range",
    what: "std::clamp(v, lo, hi) keeps a value inside the range lo..hi, inclusive. If v is below lo you get lo, if it is above hi you get hi, otherwise you get v unchanged. It is a one-call replacement for std::min(std::max(v, lo), hi), handy for limits such as volume levels, screen coordinates or percentages.",
    params: {
      v: "the value to limit, e.g. volume + 15",
      lo: "the smallest allowed value, e.g. 0",
      hi: "the largest allowed value, e.g. 100; must not be less than lo"
    },
    returns: "The limited value (technically a const reference to v, lo or hi). Store it or use it directly: int x = std::clamp(...);",
    example: "int volume = 95;                           // current level\nvolume = std::clamp(volume + 15, 0, 100);  // 110 is capped to 100\nint px = std::clamp(-5, 0, 255);           // -5 is raised to 0",
    watch: [
      "All three arguments must have the same type: std::clamp(x, 0, 100L) with an int x won't compile. Cast if needed.",
      "If lo > hi the behavior is undefined.",
      "Needs #include <algorithm> and C++17."
    ]
  }  },
  { name: 'min_element', owner: 'std', kind: 'function', sig: 'ForwardIt min_element(ForwardIt first, ForwardIt last, Compare comp = less<>())', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'comp', doc: 'comparator' }], returns: 'ForwardIt — to the first smallest element, or last if the range is empty', doc: 'Iterator to the smallest element, **O(n)**. Dereference for the value; subtract `begin()` for the index.', example: 'int mn = *min_element(v.begin(), v.end());', header: '#include <algorithm>' },
  { name: 'max_element', owner: 'std', kind: 'function', sig: 'ForwardIt max_element(ForwardIt first, ForwardIt last, Compare comp = less<>())', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'comp', doc: 'comparator' }], returns: 'ForwardIt — to the first largest element, or last if the range is empty', doc: 'Iterator to the largest element, **O(n)**. UB to dereference on an empty range.', example: 'int idx = max_element(v.begin(), v.end()) - v.begin();', header: '#include <algorithm>' },
  { name: 'swap', owner: 'std', kind: 'function', sig: 'void swap(T& a, T& b)', params: [{ label: 'a', doc: 'first object' }, { label: 'b', doc: 'second object' }], returns: 'void', doc: 'Exchange values. **O(1)** for containers (swaps internals).', example: 'swap(a[i], a[j]);', header: '#include <utility>' },
  { name: 'lower_bound', owner: 'std', kind: 'function', sig: 'ForwardIt lower_bound(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'sorted range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to search' }], returns: 'ForwardIt — first element >= value, or last', doc: 'First element **≥** value in a sorted range, **O(log n)** on random-access iterators. Index: `- v.begin()`. For set/map use the member function.', example: 'int i = lower_bound(v.begin(), v.end(), x) - v.begin();', header: '#include <algorithm>' },
  { name: 'upper_bound', owner: 'std', kind: 'function', sig: 'ForwardIt upper_bound(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'sorted range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to search' }], returns: 'ForwardIt — first element > value, or last', doc: 'First element **>** value. Count of x in sorted v: `upper_bound(...x) - lower_bound(...x)`.', example: 'int cnt = upper_bound(v.begin(), v.end(), x) - v.begin();  // # elements <= x', header: '#include <algorithm>' },
  { name: 'binary_search', owner: 'std', kind: 'function', sig: 'bool binary_search(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'sorted range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to find' }], returns: 'bool — true if an element equal to value exists', doc: 'True if *value* is in the sorted range, **O(log n)**. Returns only a bool — use `lower_bound` for the position.', example: 'bool has = binary_search(v.begin(), v.end(), x);', header: '#include <algorithm>' },
  { name: 'equal_range', owner: 'std', kind: 'function', sig: 'pair<It, It> equal_range(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'sorted range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value' }], returns: 'pair<It, It> — [lower_bound, upper_bound) for value', doc: '`{lower_bound, upper_bound}` in one call.', example: 'auto [lo, hi] = equal_range(v.begin(), v.end(), x);\nint occurrences = hi - lo;', header: '#include <algorithm>' },
  { name: 'find', owner: 'std', kind: 'function', sig: 'InputIt find(InputIt first, InputIt last, const T& value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to find' }], returns: 'InputIt — first element equal to value, or last if none', doc: 'Linear search, **O(n)**; returns *last* if not found.', example: 'if (find(v.begin(), v.end(), x) != v.end()) { }', header: '#include <algorithm>' },
  { name: 'find_if', owner: 'std', kind: 'function', sig: 'InputIt find_if(InputIt first, InputIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate' }], returns: 'InputIt — first element satisfying pred, or last if none', doc: 'First element satisfying *pred*, or *last*.', example: 'auto it = find_if(v.begin(), v.end(), [](int x) { return x < 0; });', header: '#include <algorithm>' },
  { name: 'count', owner: 'std', kind: 'function', sig: 'ptrdiff_t count(InputIt first, InputIt last, const T& value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to count' }], returns: 'ptrdiff_t — number of elements equal to value', doc: 'Number of elements equal to *value*, **O(n)**.', example: 'int ones = count(s.begin(), s.end(), \'1\');', header: '#include <algorithm>' },
  { name: 'count_if', owner: 'std', kind: 'function', sig: 'ptrdiff_t count_if(InputIt first, InputIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate' }], returns: 'ptrdiff_t — number of elements satisfying pred', doc: 'Number of elements satisfying *pred*.', example: 'int evens = count_if(v.begin(), v.end(), [](int x) { return x % 2 == 0; });', header: '#include <algorithm>' },
  { name: 'all_of', owner: 'std', kind: 'function', sig: 'bool all_of(InputIt first, InputIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate' }], returns: 'bool — true if pred holds for every element (true for an empty range)', doc: 'True if *pred* holds for every element (true for empty). See also `any_of`, `none_of`.', example: 'bool allPos = all_of(v.begin(), v.end(), [](int x) { return x > 0; });', header: '#include <algorithm>' },
  { name: 'any_of', owner: 'std', kind: 'function', sig: 'bool any_of(InputIt first, InputIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate' }], returns: 'bool — true if pred holds for some element (false for an empty range)', doc: 'True if *pred* holds for at least one element.', example: 'bool hasNeg = any_of(v.begin(), v.end(), [](int x) { return x < 0; });', header: '#include <algorithm>' },
  { name: 'none_of', owner: 'std', kind: 'function', sig: 'bool none_of(InputIt first, InputIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate' }], returns: 'bool — true if pred holds for no element (true for an empty range)', doc: 'True if *pred* holds for no element.', example: 'bool noZero = none_of(v.begin(), v.end(), [](int x) { return x == 0; });', header: '#include <algorithm>' },
  { name: 'fill', owner: 'std', kind: 'function', sig: 'void fill(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'fill value' }], returns: 'void', doc: 'Assign *value* to every element. Unlike `memset`, works for any value (e.g. `INT_MAX`).', example: 'fill(dist.begin(), dist.end(), INT_MAX);', header: '#include <algorithm>' },
  { name: 'unique', owner: 'std', kind: 'function', sig: 'ForwardIt unique(ForwardIt first, ForwardIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }], returns: 'ForwardIt — new logical end; elements after it are unspecified', doc: 'Removes **consecutive** duplicates by shifting; returns the new logical end — doesn\'t shrink the container. Sort first, then erase.', example: 'sort(v.begin(), v.end());\nv.erase(unique(v.begin(), v.end()), v.end());', header: '#include <algorithm>' },
  { name: 'remove', owner: 'std', kind: 'function', sig: 'ForwardIt remove(ForwardIt first, ForwardIt last, const T& value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'value to remove' }], returns: 'ForwardIt — new logical end (container size unchanged until you erase)', doc: 'Shifts kept elements forward and returns the new end; size is unchanged until you `erase` (erase-remove idiom). C++20: `erase(v, value)`.', example: 'v.erase(remove(v.begin(), v.end(), 0), v.end());', header: '#include <algorithm>' },
  { name: 'remove_if', owner: 'std', kind: 'function', sig: 'ForwardIt remove_if(ForwardIt first, ForwardIt last, UnaryPred pred)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'pred', doc: 'predicate for elements to drop' }], returns: 'ForwardIt — new logical end (container size unchanged until you erase)', doc: 'Like `remove` with a predicate; pair with `erase`. C++20: `erase_if(v, pred)`.', example: 'v.erase(remove_if(v.begin(), v.end(), [](int x) { return x < 0; }), v.end());', header: '#include <algorithm>' },
  { name: 'replace', owner: 'std', kind: 'function', sig: 'void replace(ForwardIt first, ForwardIt last, const T& old_value, const T& new_value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'old_value', doc: 'value to replace' }, { label: 'new_value', doc: 'replacement' }], returns: 'void', doc: 'Replace every *old_value* with *new_value*.', example: 'replace(s.begin(), s.end(), \' \', \'_\');', header: '#include <algorithm>' },
  { name: 'transform', owner: 'std', kind: 'function', sig: 'OutputIt transform(InputIt first, InputIt last, OutputIt d_first, UnaryOp op)', params: [{ label: 'first', doc: 'input begin' }, { label: 'last', doc: 'input end' }, { label: 'd_first', doc: 'output begin (may equal first)' }, { label: 'op', doc: 'function applied to each element' }], returns: 'OutputIt — one past the last element written', doc: 'Apply *op* to each element writing to *d_first*.', example: 'transform(s.begin(), s.end(), s.begin(), ::tolower);', header: '#include <algorithm>' },
  { name: 'next_permutation', owner: 'std', kind: 'function', sig: 'bool next_permutation(BidirIt first, BidirIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }], returns: 'bool — false (and the range is reset to sorted order) if it was the last permutation', doc: 'Rearrange into the next lexicographic permutation; returns false (and wraps to sorted) after the last. Sort first to enumerate all; handles duplicates.', example: 'sort(v.begin(), v.end());\ndo { use(v); } while (next_permutation(v.begin(), v.end()));', header: '#include <algorithm>' },
  { name: 'prev_permutation', owner: 'std', kind: 'function', sig: 'bool prev_permutation(BidirIt first, BidirIt last)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }], returns: 'bool — false (and the range is reset to descending order) if it was the first permutation', doc: 'Previous lexicographic permutation; false when wrapping.', example: 'sort(v.rbegin(), v.rend());\ndo { /* use v */ } while (prev_permutation(v.begin(), v.end()));', header: '#include <algorithm>' },
  { name: 'equal', owner: 'std', kind: 'function', sig: 'bool equal(InputIt1 first1, InputIt1 last1, InputIt2 first2)', params: [{ label: 'first1', doc: 'range 1 begin' }, { label: 'last1', doc: 'range 1 end' }, { label: 'first2', doc: 'range 2 begin' }], returns: 'bool — true if the ranges match element-wise', doc: 'Element-wise equality. Palindrome check: `equal(s.begin(), s.begin() + n/2, s.rbegin())`.', example: 'bool pal = equal(s.begin(), s.begin() + s.size() / 2, s.rbegin());', header: '#include <algorithm>' },
  { name: 'max with initializer list', owner: 'std', kind: 'snippet', sig: 'max({a, b, c})', doc: '`min`/`max` accept a brace list of same-typed values.', example: 'int best = max({a, b, c});', insert: 'max({${1:a}, ${2:b}, ${3:c}})', header: '#include <algorithm>' },

  // ───────────── <numeric> ─────────────
  { name: 'accumulate', owner: 'std', kind: 'function', sig: 'T accumulate(InputIt first, InputIt last, T init, BinaryOp op = plus<>())', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'init', doc: 'initial value — its type is the accumulator type!' }, { label: 'op', doc: 'combining function' }], returns: 'T — init folded with every element (computed in the type of init!)', doc: 'Fold a range. **Gotcha:** result type is the type of *init* — `accumulate(..., 0)` sums in `int` and overflows; use `0LL`.', example: 'long long s = accumulate(v.begin(), v.end(), 0LL);', header: '#include <numeric>' },
  { name: 'iota', owner: 'std', kind: 'function', sig: 'void iota(ForwardIt first, ForwardIt last, T value)', params: [{ label: 'first', doc: 'range begin' }, { label: 'last', doc: 'range end' }, { label: 'value', doc: 'starting value' }], returns: 'void', doc: 'Fill with value, value+1, …. Initialise DSU parents or an index array to sort.', example: 'vector<int> parent(n);\niota(parent.begin(), parent.end(), 0);', header: '#include <numeric>' },
  { name: 'partial_sum', owner: 'std', kind: 'function', sig: 'OutputIt partial_sum(InputIt first, InputIt last, OutputIt d_first)', params: [{ label: 'first', doc: 'input begin' }, { label: 'last', doc: 'input end' }, { label: 'd_first', doc: 'output begin (may equal first)' }], returns: 'OutputIt — one past the last element written', doc: 'Prefix sums: out[i] = in[0] + … + in[i]. Accumulates in the element type — watch overflow.', example: 'partial_sum(a.begin(), a.end(), pre.begin() + 1); // pre[0] = 0', header: '#include <numeric>' },
  { name: 'adjacent_difference', owner: 'std', kind: 'function', sig: 'OutputIt adjacent_difference(InputIt first, InputIt last, OutputIt d_first)', params: [{ label: 'first', doc: 'input begin' }, { label: 'last', doc: 'input end' }, { label: 'd_first', doc: 'output begin' }], returns: 'OutputIt — one past the last element written', doc: 'out[0] = in[0], out[i] = in[i] − in[i−1].', example: 'vector<int> d(a.size());\nadjacent_difference(a.begin(), a.end(), d.begin());  // d[0] = a[0]', header: '#include <numeric>' },
  { name: 'gcd', owner: 'std', kind: 'function', sig: 'M gcd(M m, N n)', params: [{ label: 'm', doc: 'integer' }, { label: 'n', doc: 'integer' }], returns: 'common type of M and N — greatest common divisor (non-negative; gcd(0, 0) = 0)', doc: 'C++17 greatest common divisor (of absolute values); gcd(0, 0) = 0. **O(log min)**.', example: 'int g = gcd(12, 18);  // 6', header: '#include <numeric>', learn: {
    summary: "greatest common divisor of two integers",
    what: "std::gcd(m, n) returns the greatest common divisor: the largest whole number that divides both m and n with no remainder. Typical uses are simplifying fractions (divide top and bottom by their gcd) and computing a least common multiple, a / gcd(a, b) * b (C++17 also has std::lcm). Negative inputs are treated as their absolute values, and gcd(x, 0) is |x|.",
    params: {
      m: "the first integer, e.g. 18",
      n: "the second integer, e.g. 24"
    },
    returns: "The gcd as a non-negative integer. gcd(0, 0) is 0.",
    example: "int num = 18, den = 24;                          // the fraction 18/24\nint g = std::gcd(num, den);                      // g = 6\nstd::cout << num / g << \"/\" << den / g << \"\\n\";  // prints 3/4",
    watch: [
      "Needs #include <numeric> and C++17.",
      "Both arguments must be integers; with long long values make both long long to avoid surprises."
    ]
  }  },
  { name: 'lcm', owner: 'std', kind: 'function', sig: 'M lcm(M m, N n)', params: [{ label: 'm', doc: 'integer' }, { label: 'n', doc: 'integer' }], returns: 'common type of M and N — least common multiple (0 if either is 0); may overflow', doc: 'C++17 least common multiple. Can overflow — use long long arguments.', example: 'long long l = lcm(4LL, 6LL);  // 12', header: '#include <numeric>' },

  // ───────────── misc utilities ─────────────
  { name: 'abs', owner: 'std', kind: 'function', sig: 'T abs(T x)', params: [{ label: 'x', doc: 'int, long long or floating value' }], returns: 'T — absolute value (abs(INT_MIN) overflows)', doc: 'Absolute value, overloaded for int/long long/double in C++. `abs(INT_MIN)` overflows.', example: 'int d = abs(a - b);\nlong long e = abs(x - y);  // overloaded for long long', header: '#include <cstdlib>' },
  { name: 'to_string', owner: 'std', kind: 'function', sig: 'string to_string(T value)', params: [{ label: 'value', doc: 'int, long long or double' }], returns: 'string — decimal text of value', doc: 'Number to decimal string. Doubles print 6 decimals (`"1.500000"`) — use ostringstream for control.', example: 'string s = to_string(42);  // "42"', header: '#include <string>' },
  { name: 'stoi', owner: 'std', kind: 'function', sig: 'int stoi(const string& str, size_t* pos = nullptr, int base = 10)', params: [{ label: 'str', doc: 'string' }, { label: 'pos', doc: 'receives index after the number' }, { label: 'base', doc: 'numeric base' }], returns: 'int — parsed value; throws invalid_argument / out_of_range', doc: 'Parse an int; throws `invalid_argument` on no digits and `out_of_range` on overflow.', example: 'int x = stoi("123");\nint h = stoi("ff", nullptr, 16);  // 255', header: '#include <string>' },
  { name: 'stol', owner: 'std', kind: 'function', sig: 'long stol(const string& str, size_t* pos = nullptr, int base = 10)', params: [{ label: 'str', doc: 'text to parse (leading whitespace skipped)' }, { label: 'pos', doc: 'if non-null, receives the index of the first unparsed char' }, { label: 'base', doc: 'number base (0 = auto-detect from prefix)' }], returns: 'long — parsed value; throws invalid_argument / out_of_range', doc: 'Parse a `long`. Gotcha: `long` is 64-bit on Linux/macOS but 32-bit on Windows — prefer `stoll` for portable 64-bit parsing.', example: 'long v = stol("123456789");', header: '#include <string>' },
  { name: 'stoll', owner: 'std', kind: 'function', sig: 'long long stoll(const string& str, size_t* pos = nullptr, int base = 10)', params: [{ label: 'str', doc: 'string' }, { label: 'pos', doc: 'receives index after the number' }, { label: 'base', doc: 'numeric base' }], returns: 'long long — parsed value; throws invalid_argument / out_of_range', doc: 'Parse a long long; throws on bad input.', example: 'long long big = stoll("9000000000");', header: '#include <string>' },
  { name: 'stod', owner: 'std', kind: 'function', sig: 'double stod(const string& str, size_t* pos = nullptr)', params: [{ label: 'str', doc: 'string' }, { label: 'pos', doc: 'receives index after the number' }], returns: 'double — parsed value; throws invalid_argument / out_of_range', doc: 'Parse a double.', example: 'double d = stod("3.14");', header: '#include <string>' },
  { name: 'make_pair', owner: 'std', kind: 'function', sig: 'pair<T1, T2> make_pair(T1 a, T2 b)', params: [{ label: 'a', doc: 'first' }, { label: 'b', doc: 'second' }], returns: 'pair<T1, T2> — the pair (a, b) with decayed types', doc: 'Build a pair with deduced types. Usually `{a, b}` is shorter.', example: 'pq.push(make_pair(dist, node));', header: '#include <utility>' },
  { name: 'make_tuple', owner: 'std', kind: 'function', sig: 'tuple<Ts...> make_tuple(Ts... args)', params: [{ label: 'args', doc: 'values' }], returns: 'tuple<Ts...> — tuple holding copies of args', doc: 'Build a tuple with deduced types.', example: 'auto t = make_tuple(1, \'a\', 2.5);', header: '#include <tuple>' },
  { name: 'get', owner: 'std', kind: 'function', sig: 'T& get<I>(tuple<Ts...>& t)', params: [{ label: 't', doc: 'tuple, pair or array' }], returns: 'T& — reference to element I', doc: 'Element *I* (compile-time index) of a tuple/pair/array: `get<0>(t)`.', example: 'tuple<int, string> t = {1, "x"};\nint a = get<0>(t);', header: '#include <tuple>' },
  { name: 'tie', owner: 'std', kind: 'function', sig: 'tuple<Ts&...> tie(Ts&... args)', params: [{ label: 'args', doc: 'lvalues' }], returns: 'tuple<Ts&...> — tuple of references (assign to unpack, or compare lexicographically)', doc: 'Tuple of references — unpack (`tie(a, b) = p;`) or compare lexicographically in comparators: `tie(a.x, a.y) < tie(b.x, b.y)`.', example: 'int a, b;\ntie(a, b) = make_pair(1, 2);', header: '#include <tuple>' },
  { name: 'distance', owner: 'std', kind: 'function', sig: 'ptrdiff_t distance(InputIt first, InputIt last)', params: [{ label: 'first', doc: 'start iterator' }, { label: 'last', doc: 'end iterator' }], returns: 'ptrdiff_t — number of steps from first to last (O(n) for non-random-access)', doc: 'Number of steps between iterators. **O(n)** for set/map iterators.', example: 'int idx = distance(v.begin(), it);', header: '#include <iterator>' },
  { name: 'next', owner: 'std', kind: 'function', sig: 'It next(It it, ptrdiff_t n = 1)', params: [{ label: 'it', doc: 'iterator' }, { label: 'n', doc: 'steps' }], returns: 'It — copy of it advanced by n (it is unchanged)', doc: 'Iterator advanced by *n* (copy; original unchanged).', example: 'auto second = next(s.begin());', header: '#include <iterator>' },
  { name: 'prev', owner: 'std', kind: 'function', sig: 'It prev(It it, ptrdiff_t n = 1)', params: [{ label: 'it', doc: 'bidirectional iterator' }, { label: 'n', doc: 'steps' }], returns: 'It — copy of it moved back by n (it is unchanged)', doc: 'Iterator moved back by *n*. Last element of a set/map: `*prev(s.end())`.', example: 'int largest = *prev(s.end());', header: '#include <iterator>' },
  { name: 'advance', owner: 'std', kind: 'function', sig: 'void advance(It& it, ptrdiff_t n)', params: [{ label: 'it', doc: 'iterator (modified)' }, { label: 'n', doc: 'steps' }], returns: 'void (it is modified in place)', doc: 'Move *it* by *n* in place.', example: 'auto it = l.begin();\nadvance(it, 2);', header: '#include <iterator>' },
  { name: 'move', owner: 'std', kind: 'function', sig: 'T&& move(T& t)', params: [{ label: 't', doc: 'object to move from' }], returns: 'T&& — rvalue reference to t (moves nothing by itself)', doc: 'Cast to rvalue so a container can be moved instead of copied: `res.push_back(move(path));` (path is then unspecified/empty).', example: 'vector<int> b = move(a);  // a: valid but unspecified', header: '#include <utility>' },
  { name: 'sqrt', owner: 'std', kind: 'function', sig: 'double sqrt(double x)', params: [{ label: 'x', doc: 'value' }], returns: 'double — square root (NaN for negative x)', doc: 'Square root. For integer sqrt of large values correct the floating result (or use binary search).', example: 'long long r = (long long)sqrt((double)n);\nwhile (r * r > n) r--;', header: '#include <cmath>' },
  { name: 'pow', owner: 'std', kind: 'function', sig: 'double pow(double base, double exp)', params: [{ label: 'base', doc: 'base' }, { label: 'exp', doc: 'exponent' }], returns: 'double — base raised to exp (floating point; inexact for big integers)', doc: 'Floating power — imprecise for big integers; write binary exponentiation for modular arithmetic.', example: 'double d = sqrt(pow(dx, 2) + pow(dy, 2));', header: '#include <cmath>' },
  { name: 'popcount', owner: 'std', kind: 'function', sig: 'int popcount(T x)', params: [{ label: 'x', doc: 'unsigned integer' }], returns: 'int — number of 1 bits (C++20; T must be unsigned)', doc: 'C++20 number of set bits; requires an **unsigned** type (`popcount((unsigned)x)`). See also `countl_zero`, `countr_zero`, `bit_width`.', example: 'int ones = popcount(13u);  // 3', header: '#include <bit>' },
  { name: '__builtin_popcount', kind: 'function', sig: 'int __builtin_popcount(unsigned int x)', params: [{ label: 'x', doc: 'value' }], returns: 'int — number of 1 bits in x', doc: 'GCC/Clang builtin set-bit count; `__builtin_popcountll` for 64-bit.', example: 'int ones = __builtin_popcount(mask);' },
  { name: '__builtin_popcountll', kind: 'function', sig: 'int __builtin_popcountll(unsigned long long x)', params: [{ label: 'x', doc: '64-bit value' }], returns: 'int — number of 1 bits in x', doc: '64-bit popcount (GCC/Clang builtin). Using `__builtin_popcount` on a `long long` silently truncates to 32 bits.', example: 'int ones = __builtin_popcountll(mask64);' },
  { name: '__builtin_clz', kind: 'function', sig: 'int __builtin_clz(unsigned int x)', params: [{ label: 'x', doc: 'non-zero value' }], returns: 'int — number of leading zero bits (of 32)', doc: 'Count leading zeros; `31 - __builtin_clz(x)` is floor(log2 x). **Undefined for x == 0.** Use `__builtin_clzll` for 64-bit (`63 - ...`).', example: 'int hb = 31 - __builtin_clz(n);  // index of highest set bit' },
  { name: '__builtin_ctz', kind: 'function', sig: 'int __builtin_ctz(unsigned int x)', params: [{ label: 'x', doc: 'non-zero value' }], returns: 'int — number of trailing zero bits (index of the lowest set bit)', doc: 'Count trailing zeros. **Undefined for x == 0.** Use `__builtin_ctzll` for 64-bit values.', example: 'int low = __builtin_ctz(12);  // 2' },
  { name: 'memset', owner: 'std', kind: 'function', sig: 'void* memset(void* dest, int ch, size_t count)', params: [{ label: 'dest', doc: 'memory' }, { label: 'ch', doc: 'byte value' }, { label: 'count', doc: 'bytes' }], returns: 'void* — dest', doc: 'Byte fill — only reliable for 0 and -1 on int arrays. Prefer `fill` or `vector(n, v)`.', example: 'int dp[105][105];\nmemset(dp, -1, sizeof dp);', header: '#include <cstring>' },
  { name: 'INT_MAX', kind: 'constant', sig: '#define INT_MAX 2147483647', doc: 'Max `int` (2³¹−1). `INT_MAX + 1` overflows — guard additions when using it as infinity.', example: 'int best = INT_MAX;\nfor (int x : v) best = min(best, x);', header: '#include <climits>' },
  { name: 'INT_MIN', kind: 'constant', sig: '#define INT_MIN (-2147483647 - 1)', doc: 'Min `int` (−2³¹).', example: 'int mx = INT_MIN;\nfor (int x : v) mx = max(mx, x);', header: '#include <climits>' },
  { name: 'LLONG_MAX', kind: 'constant', sig: '#define LLONG_MAX 9223372036854775807LL', doc: 'Max `long long` (≈9.2e18).', example: 'vector<long long> dist(n, LLONG_MAX);', header: '#include <climits>' },
  { name: 'LLONG_MIN', kind: 'constant', sig: '#define LLONG_MIN (-LLONG_MAX - 1)', doc: 'Min `long long`.', example: 'long long best = LLONG_MIN;', header: '#include <climits>' },
];
